INSERT INTO `berita` (`id`, `wp_id`, `wp_url`, `kategori_berita_id`, `judul`, `slug`, `konten`, `tanggal`, `thumbnail`, `total_lihat`, `created_at`, `updated_at`) VALUES
('249', '68937', 'https://berita.kendarikota.go.id/semangat-juang-tinggi-diskominfo-kota-kendari-sabet-juara-badminton-hari-bakti-postel-ke-81/', '10', 'Semangat Juang Tinggi, Diskominfo Kota Kendari Sabet Juara Badminton Hari Bakti Postel ke-81', 'semangat-juang-tinggi-diskominfo-kota-kendari-sabet-juara-badminton-hari-bakti-postel-ke-81', '\n<p>Kendari, kendarikota.go.id — Dinas Komunikasi dan Informatika (Diskominfo) Kota Kendari sukses meraih juara pertama turnamen badminton dalam rangka memperingati Hari Bakti Postel ke-81 yang digelar Balai Monitor Spektrum Frekuensi Radio dan Infrastruktur Digital (Balmon) Kelas II Kendari, Rabu (16/9/2026).</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img decoding=\"async\" width=\"1024\" height=\"768\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA0039-1024x768.jpg\" alt class=\"wp-image-68938\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA0039-1024x768.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA0039-300x225.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA0039-768x576.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA0039-750x563.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA0039-1140x855.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA0039.jpg 1280w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Tim Diskominfo Kota Kendari yang dipimpin Kadis Kominfo Kota Kendari, Sahuriyanto, tampil penuh semangat sejak babak penyisihan.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA0030-1024x576.jpg\" alt class=\"wp-image-68939\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA0030-1024x576.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA0030-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA0030-768x432.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA0030-1536x864.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA0030-2048x1152.jpg 2048w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA0030-750x422.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA0030-1140x641.jpg 1140w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Pada laga pertama, Diskominfo menghadapi RRI Kendari. Tampil dominan sejak awal pertandingan, pasangan Diskominfo berhasil mengamankan kemenangan dua set langsung dengan skor 21-14 dan 21-7.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img decoding=\"async\" width=\"1024\" height=\"768\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA0034-1024x768.jpg\" alt class=\"wp-image-68940\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA0034-1024x768.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA0034-300x225.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA0034-768x576.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA0034-1536x1152.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA0034-2048x1536.jpg 2048w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA0034-750x563.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA0034-1140x855.jpg 1140w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Perjuangan berlanjut menghadapi PT Telkom. Pertandingan berlangsung ketat hingga harus dimainkan dalam tiga set. Dengan permainan yang solid dan kerja sama tim yang baik, Diskominfo berhasil mengatasi perlawanan PT Telkom dan melaju ke semifinal.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"768\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA00251-1024x768.jpg\" alt class=\"wp-image-68942\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA00251-1024x768.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA00251-300x225.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA00251-768x576.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA00251-1536x1152.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA00251-2048x1536.jpg 2048w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA00251-750x563.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260917-WA00251-1140x855.jpg 1140w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Di babak semifinal, Diskominfo berhadapan dengan Organisasi Amatir Radio Republik Indonesia (ORARI). Permainan konsisten dan kekompakan tim mengantarkan Diskominfo meraih kemenangan sekaligus memastikan tempat di partai final.</p>\n\n\n\n<p>Pada partai puncak, Diskominfo menghadapi PT Pos Indonesia. Tampil percaya diri dan mampu menjaga konsistensi permainan, tim Diskominfo berhasil mengalahkan PT Pos Indonesia dua set langsung.</p>\n\n\n\n<p>Kadis Kominfo Kota Kendari, Sahuriyanto, menyampaikan apresiasi kepada seluruh tim yang telah berjuang dengan penuh semangat dan menjunjung tinggi sportivitas selama pertandingan.</p>\n\n\n\n<p>Menurutnya, keikutsertaan dalam kegiatan tersebut bukan hanya untuk mengejar prestasi, tetapi juga menjadi momentum mempererat silaturahmi dan membangun kekompakan antarinstansi dalam semangat Hari Bakti Postel ke-81.</p>\n\n\n\n<p>“Prestasi ini tentu menjadi kebanggaan bagi kami. Yang paling penting adalah semangat kebersamaan, kekompakan, dan sportivitas yang terbangun melalui kegiatan ini,” ujarnya.</p>\n\n\n\n<p>Hasil tersebut memastikan Diskominfo Kota Kendari keluar sebagai juara pertama turnamen badminton Hari Bakti Postel ke-81.</p>\n', '2026-09-17', 'berita/kY5CCV14Vv.webp', '10', '2026-09-23 18:16:20', '2026-10-25 05:07:40'),
('250', '68635', 'https://berita.kendarikota.go.id/kominfo-kendari-perkuat-sinergi-dengan-loka-monitor-komdigi-jelang-hari-bakti-postel-ke-811/', '10', 'Kominfo Kendari Perkuat Sinergi dengan Balai Monitor Spektrum Frekuensi Radio dan Infrastruktur Digital Kelas II Kendari Jelang Hari Bakti Postel ke-81', 'kominfo-kendari-perkuat-sinergi-dengan-balai-monitor-spektrum-frekuensi-radio-dan-infrastruktur-digital-kelas-ii-kendari-jelang-hari-bakti-postel-ke-81', '\n<p>Kendari, kendarikota.go.id – Kepala Dinas Komunikasi dan Informatika (Kominfo) Kota Kendari Sahuriyanto Meronda menghadiri rapat koordinasi bersama Balai Monitor Spektrum Frekuensi Radio dan Infrastruktur Digital Kelas II Kendari, Selasa (8/9/2026).</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-1 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" data-id=\"68636\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/851b84df-6165-4a48-bcfa-456e3a2ecf11-1024x576.jpeg\" alt class=\"wp-image-68636\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/851b84df-6165-4a48-bcfa-456e3a2ecf11-1024x576.jpeg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/851b84df-6165-4a48-bcfa-456e3a2ecf11-300x169.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/851b84df-6165-4a48-bcfa-456e3a2ecf11-768x432.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/851b84df-6165-4a48-bcfa-456e3a2ecf11-1536x864.jpeg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/851b84df-6165-4a48-bcfa-456e3a2ecf11-750x422.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/851b84df-6165-4a48-bcfa-456e3a2ecf11-1140x641.jpeg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/851b84df-6165-4a48-bcfa-456e3a2ecf11.jpeg 1599w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n</figure>\n\n\n\n<p>Pertemuan tersebut digelar sebagai bagian dari persiapan rangkaian peringatan Hari Bakti Postel ke-81 yang akan dilaksanakan pada 27 September 2026.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-2 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" data-id=\"68637\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/923cebd4-ccad-49ad-acef-fa463156c68c-1024x576.jpeg\" alt class=\"wp-image-68637\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/923cebd4-ccad-49ad-acef-fa463156c68c-1024x576.jpeg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/923cebd4-ccad-49ad-acef-fa463156c68c-300x169.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/923cebd4-ccad-49ad-acef-fa463156c68c-768x432.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/923cebd4-ccad-49ad-acef-fa463156c68c-1536x864.jpeg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/923cebd4-ccad-49ad-acef-fa463156c68c-750x422.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/923cebd4-ccad-49ad-acef-fa463156c68c-1140x641.jpeg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/923cebd4-ccad-49ad-acef-fa463156c68c.jpeg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n</figure>\n\n\n\n<p>Rapat koordinasi tersebut membahas berbagai persiapan agenda peringatan Hari Bakti Postel sekaligus memperkuat sinergi antara Pemerintah Kota Kendari dan Balai Monitor Spektrum Frekuensi Radio dan Infrastruktur Digital Kelas II Kendari, khususnya dalam bidang komunikasi dan telekomunikasi. Sejumlah kegiatan telah disiapkan untuk memeriahkan peringatan tersebut.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-3 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" data-id=\"68638\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/988fd836-229f-4d75-8dbb-408e6b27e91c-1024x576.jpeg\" alt class=\"wp-image-68638\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/988fd836-229f-4d75-8dbb-408e6b27e91c-1024x576.jpeg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/988fd836-229f-4d75-8dbb-408e6b27e91c-300x169.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/988fd836-229f-4d75-8dbb-408e6b27e91c-768x432.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/988fd836-229f-4d75-8dbb-408e6b27e91c-1536x864.jpeg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/988fd836-229f-4d75-8dbb-408e6b27e91c-750x422.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/988fd836-229f-4d75-8dbb-408e6b27e91c-1140x641.jpeg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/988fd836-229f-4d75-8dbb-408e6b27e91c.jpeg 1599w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n</figure>\n\n\n\n<p>Dalam kesempatan itu, pihak Balai Monitor Spektrum Frekuensi Radio dan Infrastruktur Digital Kelas II Kendari memaparkan sejumlah agenda yang direncanakan, di antaranya pertandingan bulu tangkis, tenis meja, jalan santai, donor darah serta berbagai kegiatan lainnya. Rangkaian kegiatan tersebut diharapkan dapat menjadi wadah kebersamaan sekaligus memperkenalkan peran Balai Monitor kepada masyarakat.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-4 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" data-id=\"68639\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/c8e92e62-1c9d-4b67-a429-863cd1cc2def-1024x576.jpeg\" alt class=\"wp-image-68639\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/c8e92e62-1c9d-4b67-a429-863cd1cc2def-1024x576.jpeg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/c8e92e62-1c9d-4b67-a429-863cd1cc2def-300x169.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/c8e92e62-1c9d-4b67-a429-863cd1cc2def-768x432.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/c8e92e62-1c9d-4b67-a429-863cd1cc2def-1536x864.jpeg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/c8e92e62-1c9d-4b67-a429-863cd1cc2def-750x422.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/c8e92e62-1c9d-4b67-a429-863cd1cc2def-1140x641.jpeg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/c8e92e62-1c9d-4b67-a429-863cd1cc2def.jpeg 1599w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n</figure>\n\n\n\n<p>Kepala Dinas Kominfo Kota Kendari Sahuriyanto Meronda menyambut baik rencana tersebut. Menurutnya, momentum Hari Bakti Postel ke-81 dapat dimanfaatkan untuk memperkenalkan keberadaan dan tugas Balai Monitor Spektrum Frekuensi Radio dan Infrastruktur Digital Kelas II Kendari kepada masyarakat Kota Kendari yang dinilai masih belum banyak mengetahui peran lembaga tersebut.</p>\n\n\n\n<p>“Karena status dan keberadaan lembaga ini memang perlu kita publikasikan kepada masyarakat. Saya juga membawa tim untuk dibuatkan publikasi, supaya keberadaan Balai Monitor ini lebih dikenal,” ujar Kepala Dinas Kominfo.</p>\n\n\n\n<p>Ia menjelaskan, Balai Monitor memiliki peran penting dalam pengawasan frekuensi radio serta pemantauan kualitas layanan telekomunikasi di wilayah kerja.</p>\n\n\n\n<p>Sahuriyanto menilai berbagai kegiatan yang telah disiapkan menjadi momentum yang tepat untuk membangun kedekatan dengan masyarakat sekaligus memperkuat koordinasi. Balai Monitor Spektrum Frekuensi Radio dan Infrastruktur Digital Kelas II Kendari juga membuka ruang bagi masyarakat untuk menyampaikan laporan apabila menemukan persoalan terkait kualitas layanan telekomunikasi, termasuk wilayah yang mengalami kualitas sinyal kurang baik.</p>\n\n\n\n<p>Dalam rapat tersebut, Kepala Balai Monitor Spektrum Frekuensi Radio dan Infrastruktur Digital Kelas II Kendari, Boby Satriyo turut menyampaikan harapan agar Wali Kota Kendari dapat hadir sekaligus menjadi pembina upacara pada puncak peringatan Hari Bakti Postel ke-81, 27 September 2026.</p>\n\n\n\n<p>Kehadiran Wali Kota diharapkan menjadi bentuk dukungan Pemerintah Kota Kendari terhadap keberadaan Balai Monitor sekaligus memperkuat kolaborasi dalam meningkatkan kualitas layanan komunikasi dan telekomunikasi bagi masyarakat.</p>\n\n\n\n<p></p>\n', '2026-09-10', 'berita/JICu8leM1y.webp', '8', '2026-09-23 18:16:20', '2026-10-25 05:07:42'),
('251', '68602', 'https://berita.kendarikota.go.id/damkar-kendari-bantu-lepaskan-cincin-anak-magang-kominfo/', '10', 'Damkar Kendari Bantu Lepaskan Cincin Anak Magang Kominfo', 'damkar-kendari-bantu-lepaskan-cincin-anak-magang-kominfo', '\n<p>Kendari, kendarikota.go.id – Tim Rescue Pleton 1 Dinas Pemadam Kebakaran (Damkar) Kota Kendari bergerak cepat memberikan bantuan penyelamatan kepada salah seorang anak magang di Dinas Komunikasi dan Informatika (Kominfo) Kota Kendari yang mengalami pembengkakan pada jari akibat kecelakaan, Selasa (8/9/2026).</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-5 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" data-id=\"68604\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/05b09bc7-5002-4dbe-99fc-fd2c79539cfd-1024x576.jpeg\" alt class=\"wp-image-68604\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/05b09bc7-5002-4dbe-99fc-fd2c79539cfd-1024x576.jpeg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/05b09bc7-5002-4dbe-99fc-fd2c79539cfd-300x169.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/05b09bc7-5002-4dbe-99fc-fd2c79539cfd-768x432.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/05b09bc7-5002-4dbe-99fc-fd2c79539cfd-1536x864.jpeg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/05b09bc7-5002-4dbe-99fc-fd2c79539cfd-750x422.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/05b09bc7-5002-4dbe-99fc-fd2c79539cfd-1140x641.jpeg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/05b09bc7-5002-4dbe-99fc-fd2c79539cfd.jpeg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n</figure>\n\n\n\n<p>Anak magang bernama Fira tersebut mengalami pembengkakan pada jari yang terpasang cincin. Kondisi tersebut membuat cincin sulit dilepaskan sehingga membutuhkan penanganan dari tim penyelamatan Damkar Kota Kendari.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-6 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" data-id=\"68605\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/8519c6a0-64bc-4e85-8d8d-64b80be7d486-1024x576.jpeg\" alt class=\"wp-image-68605\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/8519c6a0-64bc-4e85-8d8d-64b80be7d486-1024x576.jpeg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/8519c6a0-64bc-4e85-8d8d-64b80be7d486-300x169.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/8519c6a0-64bc-4e85-8d8d-64b80be7d486-768x432.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/8519c6a0-64bc-4e85-8d8d-64b80be7d486-1536x864.jpeg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/8519c6a0-64bc-4e85-8d8d-64b80be7d486-750x422.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/8519c6a0-64bc-4e85-8d8d-64b80be7d486-1140x641.jpeg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/8519c6a0-64bc-4e85-8d8d-64b80be7d486.jpeg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n</figure>\n\n\n\n<p>Tim Rescue Pleton 1 yang dipimpin oleh Danton Muslim, S.Si., bersama empat orang anggota kemudian melakukan tindakan untuk melepaskan cincin dari jari Fira. Proses pelepasan dilakukan dengan hati-hati dan menggunakan teknik serta peralatan yang sesuai untuk memastikan keselamatan korban.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-7 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"582\" height=\"1024\" data-id=\"68606\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/6f8d5a89-f5b5-4d28-9577-2a1916b299fe-582x1024.jpeg\" alt class=\"wp-image-68606\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/6f8d5a89-f5b5-4d28-9577-2a1916b299fe-582x1024.jpeg 582w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/6f8d5a89-f5b5-4d28-9577-2a1916b299fe-171x300.jpeg 171w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/6f8d5a89-f5b5-4d28-9577-2a1916b299fe-768x1350.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/6f8d5a89-f5b5-4d28-9577-2a1916b299fe-874x1536.jpeg 874w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/6f8d5a89-f5b5-4d28-9577-2a1916b299fe-750x1319.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/6f8d5a89-f5b5-4d28-9577-2a1916b299fe.jpeg 910w\" sizes=\"(max-width: 582px) 100vw, 582px\" /></figure>\n</figure>\n\n\n\n<p>Berkat respons cepat dan penanganan yang dilakukan tim Damkar, cincin yang terpasang pada jari Fira akhirnya berhasil dilepaskan. Proses tersebut berlangsung di Kantor Dinas Kominfo Kota Kendari.</p>\n\n\n\n<p>Sekretaris Dinas Kominfo Kota Kendari, Wawan Astanto, menyampaikan apresiasi kepada Tim Rescue Pleton 1 Damkar Kota Kendari atas respons cepat dalam membantu anak magang yang mengalami kondisi tersebut.</p>\n\n\n\n<p>Menurutnya, kehadiran dan kesiapsiagaan petugas Damkar tidak hanya berkaitan dengan penanganan kebakaran, tetapi juga memberikan pelayanan penyelamatan kepada masyarakat dalam berbagai kondisi darurat.</p>\n\n\n\n<p>Wawan berharap sinergi dan koordinasi antara perangkat daerah di lingkungan Pemerintah Kota Kendari terus terjalin dengan baik. Ia juga mengapresiasi dedikasi Tim Damkar Kota Kendari yang sigap memberikan bantuan ketika dibutuhkan.</p>\n\n\n\n<p></p>\n', '2026-09-08', 'berita/3fxIAk0dmD.webp', '5', '2026-09-23 18:16:20', '2026-10-25 05:07:52'),
('252', '67527', 'https://berita.kendarikota.go.id/kadis-kominfo-kota-kendari-berikan-edukasi-cerdas-bermedia-dan-bijak-menggunakan-handphone-kepada-siswa-sekolah-rakyat/', '10', 'Kadis Kominfo kota Kendari Berikan Edukasi Cerdas Bermedia dan Bijak Menggunakan Handphone kepada Siswa Sekolah Rakyat', 'kadis-kominfo-kota-kendari-berikan-edukasi-cerdas-bermedia-dan-bijak-menggunakan-handphone-kepada-siswa-sekolah-rakyat', '\n<p>Kendari, kendarikota.go.id – Kepala Dinas Komunikasi dan Informatika (Kominfo) Kota Kendari, Sahuriyanto Meronda, SP., MM, menjadi salah satu pemateri dalam kegiatan Masa Pengenalan Lingkungan Sekolah (MPLS) Sekolah Rakyat Terintegrasi 2 Kota Kendari Tahun Ajaran 2026/2027, Senin (10/8/2026).</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0137-1024x576.jpg\" alt class=\"wp-image-67528\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0137-1024x576.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0137-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0137-768x432.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0137-1536x864.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0137-750x422.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0137-1140x641.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0137.jpg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Kegiatan yang berlangsung pada 29 Juli hingga 10 Agustus 2026 tersebut dilaksanakan di Kelurahan Abeli Dalam, Kecamatan Puuwatu, Kota Kendari, sebagai langkah awal bagi peserta didik baru untuk mengenal lingkungan sekolah sekaligus mendapatkan pembinaan karakter, kedisiplinan, dan semangat belajar.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0133-1024x576.jpg\" alt class=\"wp-image-67529\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0133-1024x576.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0133-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0133-768x432.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0133-1536x864.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0133-750x422.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0133-1140x641.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0133.jpg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Dalam kegiatan tersebut, Sahuriyanto membawakan materi mengenai “Cerdas Bermedia dan Bijak Menggunakan Handphone”, dengan fokus pada penggunaan media sosial dan internet yang sehat serta pemanfaatan handphone secara positif dan produktif.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0140-1024x576.jpg\" alt class=\"wp-image-67530\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0140-1024x576.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0140-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0140-768x432.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0140-1536x864.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0140-750x422.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0140-1140x641.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0140.jpg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Di hadapan para peserta didik, Sahuriyanto mengajak siswa memahami bahwa perkembangan teknologi digital memberikan banyak manfaat apabila digunakan secara tepat. Internet dan media sosial, menurutnya, tidak seharusnya hanya digunakan untuk hiburan atau sekadar melihat konten, tetapi juga dapat menjadi sarana belajar, berkreasi, berkomunikasi, membangun prestasi hingga membuka peluang usaha.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0134-1024x576.jpg\" alt class=\"wp-image-67531\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0134-1024x576.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0134-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0134-768x432.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0134-1536x864.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0134-750x422.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0134-1140x641.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0134.jpg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>“Media sosial ini bukan hanya tempat scroll. Kita bisa mendapatkan informasi, belajar, berkarya, berprestasi, berbagi kreativitas, bahkan mendukung usaha dan membangun reputasi diri melalui konten-konten positif,” ujarnya.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0132-1024x576.jpg\" alt class=\"wp-image-67532\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0132-1024x576.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0132-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0132-768x432.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0132-1536x864.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0132-750x422.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0132-1140x641.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0132.jpg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Ia juga mengingatkan peserta didik untuk berhati-hati dalam menggunakan media sosial karena setiap unggahan dapat menjadi bagian dari jejak digital yang tersimpan dalam waktu lama.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0125-1024x576.jpg\" alt class=\"wp-image-67533\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0125-1024x576.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0125-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0125-768x432.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0125-1536x864.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0125-750x422.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0125-1140x641.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0125.jpg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Menurutnya, siswa perlu membiasakan diri berpikir sebelum mengunggah, berkomentar maupun membagikan sebuah informasi.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0141-1024x576.jpg\" alt class=\"wp-image-67534\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0141-1024x576.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0141-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0141-768x432.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0141-1536x864.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0141-750x422.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0141-1140x641.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260810-WA0141.jpg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Sahuriyanto memperkenalkan prinsip sederhana kepada peserta didik, yakni membaca terlebih dahulu, tidak bereaksi ketika emosi, memeriksa kebenaran informasi, memikirkan dampaknya, kemudian baru mengunggah atau membagikannya.</p>\n\n\n\n<p>“Kita harus cepat membaca, tetapi lambat membagikan. Sebelum share, periksa dulu apakah informasinya benar, aman, bermanfaat dan tidak merugikan diri sendiri maupun orang lain,” jelasnya.</p>\n\n\n\n<p>Selain persoalan hoaks, ia juga memberikan pemahaman mengenai berbagai risiko di ruang digital, seperti kecanduan media sosial, perundungan atau cyberbullying, penyalahgunaan data pribadi, penipuan online, akun diretas serta penyebaran konten yang tidak pantas.</p>\n\n\n\n<p>Para siswa juga diingatkan agar tidak sembarangan membagikan data pribadi, tautan mencurigakan maupun informasi yang belum terverifikasi. Sahuriyanto menekankan pentingnya menjaga keamanan akun, termasuk memanfaatkan fitur keamanan seperti autentikasi dua faktor.</p>\n\n\n\n<p>Handphone Harus Dimanfaatkan Secara Produktif</p>\n\n\n\n<p>Pada materi berikutnya, Sahuriyanto mengajak siswa mengubah cara pandang terhadap penggunaan handphone.</p>\n\n\n\n<p>Menurutnya, persoalan utama bukan sekadar boleh atau tidak boleh menggunakan handphone, melainkan untuk apa handphone digunakan dan berapa lama penggunaannya.</p>\n\n\n\n<p>“Bukan hanya boleh pakai HP atau tidak, tetapi dipakai untuk apa dan berapa lama? Handphone yang sama ketika berada di tangan kita bisa memberikan hasil yang berbeda, tergantung bagaimana kita menggunakannya,” katanya.</p>\n\n\n\n<p>Ia mendorong peserta didik memanfaatkan handphone untuk berbagai kegiatan positif, seperti belajar, mencari referensi, mengerjakan tugas, berkomunikasi, membuat karya, menghasilkan konten kreatif serta mengembangkan keterampilan.</p>\n\n\n\n<p>Sahuriyanto juga mengingatkan agar penggunaan handphone tidak sampai mengganggu aktivitas utama siswa, seperti belajar, berinteraksi dengan keluarga, beristirahat dan menjalankan kewajiban sehari-hari.</p>\n\n\n\n<p>Dalam kesempatan tersebut, ia turut mengapresiasi penerapan pembatasan penggunaan media sosial dan handphone di lingkungan Sekolah Rakyat sebagai bagian dari upaya menciptakan suasana belajar yang lebih fokus.</p>\n\n\n\n<p>Ia berharap para peserta didik Sekolah Rakyat dapat menjadi generasi yang tidak hanya mampu menggunakan teknologi, tetapi juga memiliki literasi digital, etika, tanggung jawab dan kemampuan untuk memanfaatkan teknologi secara produktif.</p>\n\n\n\n<p>“Tujuan akhirnya adalah bagaimana kita membentuk masyarakat yang cakap digital, aman dan produktif. Anak-anak inilah yang nantinya menjadi generasi penerus, sehingga sejak sekarang harus dibekali kemampuan untuk menggunakan teknologi secara cerdas dan bijak,” tuturnya.</p>\n\n\n\n<p>Kegiatan MPLS Sekolah Rakyat Terintegrasi 2 Kota Kendari sendiri menjadi bagian dari pembinaan awal peserta didik, dengan melibatkan dukungan berbagai pihak sesuai bidang masing-masing, sehingga proses pengenalan lingkungan sekolah tidak hanya berorientasi pada pendidikan akademik, tetapi juga pembentukan karakter dan keterampilan peserta didik dalam menghadapi perkembangan zaman.</p>\n', '2026-08-10', 'berita/oKS3gOuvfG.webp', '8', '2026-09-23 18:16:20', '2026-10-25 05:07:53'),
('253', '67259', 'https://berita.kendarikota.go.id/kadis-kominfo-kendari-terima-kunjungan-rri-bahas-peluang-kerja-sama-publikasi-dan-diseminasi-informasi/', '10', 'Kadis Kominfo Kendari Terima Kunjungan RRI, Bahas Peluang Kerja Sama Publikasi dan Diseminasi Informasi', 'kadis-kominfo-kendari-terima-kunjungan-rri-bahas-peluang-kerja-sama-publikasi-dan-diseminasi-informasi', '\n<p>Kendari, kendarikota.go.id – Pemerintah Kota Kendari terus memperkuat kolaborasi dengan berbagai lembaga penyiaran guna memperluas jangkauan informasi kepada masyarakat. Salah satu upaya tersebut diwujudkan melalui pertemuan antara Dinas Komunikasi dan Informatika (Kominfo) Kota Kendari dengan jajaran pengelola redaksi Radio Republik Indonesia (RRI) Kendari, yang berlangsung di Kantor Dinas Kominfo Kota Kendari, Selasa (4/8/2026).</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0162-1024x576.jpg\" alt class=\"wp-image-67260\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0162-1024x576.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0162-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0162-768x432.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0162-1536x864.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0162-2048x1152.jpg 2048w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0162-750x422.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0162-1140x641.jpg 1140w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Kunjungan pengelola redaksi RRI diterima langsung oleh Kepala Dinas Kominfo Kota Kendari, Sahuriyanto Meronda. Pertemuan berlangsung dalam suasana akrab dengan agenda utama membahas rencana kerja sama antara Pemerintah Kota Kendari dan RRI yang akan dituangkan dalam bentuk nota kesepahaman (MoU).</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0163-1024x576.jpg\" alt class=\"wp-image-67261\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0163-1024x576.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0163-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0163-768x432.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0163-1536x864.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0163-2048x1152.jpg 2048w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0163-750x422.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0163-1140x641.jpg 1140w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Sahuriyanto Meronda menyambut baik inisiatif tersebut. Menurutnya, sinergi antara pemerintah daerah dan lembaga penyiaran publik memiliki peran strategis dalam mendukung penyebarluasan informasi pembangunan sekaligus meningkatkan kualitas komunikasi publik.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0158-1024x576.jpg\" alt class=\"wp-image-67262\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0158-1024x576.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0158-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0158-768x432.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0158-1536x864.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0158-2048x1152.jpg 2048w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0158-750x422.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0158-1140x641.jpg 1140w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>“Kolaborasi ini diharapkan mampu memperkuat penyampaian informasi kepada masyarakat. Pemerintah Kota Kendari tentu terbuka untuk membangun kerja sama dengan berbagai media, termasuk RRI, dalam mendukung keterbukaan informasi publik dan publikasi program-program pemerintah,” ujar Sahuriyanto.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0142-1024x576.jpg\" alt class=\"wp-image-67263\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0142-1024x576.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0142-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0142-768x432.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0142-750x422.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0142-1140x641.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/08/IMG-20260804-WA0142.jpg 1280w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Ia menjelaskan, perkembangan teknologi informasi menuntut pemerintah untuk menghadirkan komunikasi publik yang cepat, akurat, dan mudah diakses masyarakat. Karena itu, kehadiran RRI sebagai lembaga penyiaran publik dinilai menjadi mitra strategis dalam menyampaikan berbagai informasi yang edukatif, informatif, dan bermanfaat.</p>\n\n\n\n<p>Dalam pertemuan tersebut, kedua belah pihak juga mendiskusikan sejumlah peluang kerja sama, mulai dari publikasi program pembangunan daerah, penyebarluasan informasi kebijakan pemerintah, edukasi kepada masyarakat, hingga dukungan terhadap berbagai kegiatan yang dilaksanakan Pemerintah Kota Kendari.</p>\n\n\n\n<p>Sahuriyanto berharap rencana penandatanganan nota kesepahaman dapat segera direalisasikan sehingga menjadi landasan kerja sama yang lebih terarah dan berkelanjutan.</p>\n\n\n\n<p>“Harapannya, melalui MoU nantinya, sinergi antara Pemerintah Kota Kendari dan RRI semakin kuat dalam mendukung penyebaran informasi yang kredibel serta meningkatkan literasi informasi masyarakat,” katanya.</p>\n\n\n\n<p>Sementara itu, jajaran pengelola redaksi RRI menyampaikan apresiasi atas sambutan yang diberikan Dinas Kominfo Kota Kendari. Mereka berharap komunikasi yang telah terjalin dapat ditindaklanjuti melalui kerja sama resmi sehingga RRI dapat berkontribusi lebih besar dalam mendukung penyebarluasan informasi pembangunan dan pelayanan publik di Kota Kendari.</p>\n\n\n\n<p>Pertemuan tersebut menjadi langkah awal memperkuat kemitraan antara Pemerintah Kota Kendari dan RRI dalam menghadirkan layanan informasi publik yang semakin efektif, menjangkau seluruh lapisan masyarakat, serta mendukung terwujudnya tata kelola pemerintahan yang terbuka, transparan, dan partisipatif.</p>\n', '2026-08-04', 'berita/hXZPP9wEJw.webp', '5', '2026-09-23 18:16:20', '2026-10-25 05:07:56'),
('254', '66287', 'https://berita.kendarikota.go.id/diskominfo-kota-bontang-belajar-transformasi-digital-di-kendari-tertarik-sistem-command-center-dan-call-center-112/', '10', 'Diskominfo Kota Bontang Belajar Transformasi Digital di Kendari, Tertarik Sistem Command Center dan Call Center 112', 'diskominfo-kota-bontang-belajar-transformasi-digital-di-kendari-tertarik-sistem-command-center-dan-call-center-112', '\n<p>Kendari, kendarikota.go.id – Keberhasilan Pemerintah Kota Kendari mengembangkan sistem pemerintahan berbasis digital menarik perhatian daerah lain. Dinas Komunikasi dan Informatika (Diskominfo) Kota Bontang, Kalimantan Timur, melakukan kunjungan studi tiru ke Diskominfo Kota Kendari untuk mempelajari pengelolaan e-government, strategi komunikasi publik, hingga layanan pengaduan masyarakat melalui Call Center 112. Kegiatan ini berlangsung di Command Center Diskominfo Kota Kendari, Senin (6/7/2026).</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"768\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/07/IMG-20260706-WA0121-1024x768.jpg\" alt class=\"wp-image-66288\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/07/IMG-20260706-WA0121-1024x768.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/07/IMG-20260706-WA0121-300x225.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/07/IMG-20260706-WA0121-768x576.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/07/IMG-20260706-WA0121-1536x1152.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/07/IMG-20260706-WA0121-750x563.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/07/IMG-20260706-WA0121-1140x855.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/07/IMG-20260706-WA0121.jpg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Kunjungan yang dipimpin Kepala Diskominfo Kota Bontang, Andi Hasanuddin Akmal, bersama Kasubag Umum Diskominfo Bontang, diterima langsung Kepala Diskominfo Kota Kendari, Sahuriyanto Meronda, bersama jajaran.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"768\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/07/IMG-20260706-WA0123-1024x768.jpg\" alt class=\"wp-image-66289\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/07/IMG-20260706-WA0123-1024x768.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/07/IMG-20260706-WA0123-300x225.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/07/IMG-20260706-WA0123-768x576.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/07/IMG-20260706-WA0123-750x563.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/07/IMG-20260706-WA0123-1140x855.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/07/IMG-20260706-WA0123.jpg 1280w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Dalam pertemuan tersebut, Kadis Kominfo memaparkan berbagai inovasi digital yang telah dikembangkan Pemerintah Kota Kendari sebagai bagian dari transformasi pelayanan publik. Salah satu yang menjadi perhatian adalah integrasi website resmi pemerintah dengan seluruh kanal media sosial sehingga informasi pembangunan dapat diakses masyarakat secara cepat dan luas.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"768\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/07/IMG-20260706-WA0122-1024x768.jpg\" alt class=\"wp-image-66290\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/07/IMG-20260706-WA0122-1024x768.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/07/IMG-20260706-WA0122-300x225.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/07/IMG-20260706-WA0122-768x576.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/07/IMG-20260706-WA0122-1536x1152.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/07/IMG-20260706-WA0122-750x563.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/07/IMG-20260706-WA0122-1140x855.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/07/IMG-20260706-WA0122.jpg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Menurutnya, perkembangan teknologi telah mengubah pola komunikasi pemerintah dengan masyarakat. Karena itu, pemerintah daerah harus mampu memanfaatkan platform digital sebagai sarana penyampaian informasi sekaligus media untuk menangkap aspirasi masyarakat.</p>\n\n\n\n<p>“Kami terus memperkuat tata kelola pemerintahan berbasis elektronik. Selain melalui website resmi, seluruh aktivitas pemerintah juga dipublikasikan melalui media sosial agar informasi dapat diterima masyarakat secara lebih cepat dan mudah,” kata Sahuriyanto.</p>\n\n\n\n<p>Ia mengungkapkan, selama Januari hingga Juni 2026, portal resmi Pemerintah Kota Kendari telah mempublikasikan 733 berita dengan rata-rata empat berita setiap hari. Dalam periode tersebut, website pemerintah juga mencatat lebih dari 25 ribu pengunjung dengan total tayangan mencapai sekitar 2,2 juta kali.</p>\n\n\n\n<p>Selain pengelolaan informasi, Sahuriyanto juga menjelaskan perkembangan layanan Call Center 112 yang kini menjadi salah satu kanal utama pengaduan masyarakat selama 24 jam.</p>\n\n\n\n<p>Layanan tersebut telah terintegrasi dengan berbagai organisasi perangkat daerah serta instansi vertikal, seperti PLN, Basarnas, Polres, Kodim, hingga Satpol PP. Menurutnya, kolaborasi lintas sektor menjadi faktor penting agar setiap laporan masyarakat dapat segera ditindaklanjuti.</p>\n\n\n\n<p>“Call Center 112 bukan sekadar menerima laporan, tetapi menjadi pusat koordinasi pelayanan publik. Semua pengaduan langsung diteruskan kepada instansi yang berwenang sehingga penanganannya lebih cepat dan terukur,” jelasnya.</p>\n\n\n\n<p>Ke depan, Pemerintah Kota Kendari juga berencana memperkuat fungsi Command Center melalui penambahan kamera pengawas (CCTV) dan pengembangan sistem pemantauan digital untuk mendukung pelayanan publik yang semakin responsif.</p>\n\n\n\n<p>Sementara itu, Kepala Diskominfo Kota Bontang, Andi Hasanuddin Akmal, mengaku banyak memperoleh referensi dari pengelolaan transformasi digital yang diterapkan Pemerintah Kota Kendari.</p>\n\n\n\n<p>Ia menilai keberhasilan Kendari mengintegrasikan website, media sosial, Command Center, dan Call Center 112 menjadi satu ekosistem pelayanan publik merupakan langkah yang patut dicontoh.</p>\n\n\n\n<p>“Kami melihat Kota Kendari berhasil membangun sistem komunikasi publik yang terintegrasi. Pengelolaan media digitalnya sangat aktif, tingkat jangkauannya tinggi, dan layanan Call Center 112 mampu melibatkan banyak instansi dalam satu sistem. Pengalaman ini menjadi bekal penting bagi kami untuk terus meningkatkan pelayanan digital di Kota Bontang,” ujar Andi.</p>\n\n\n\n<p>Ia juga mengapresiasi fasilitas Command Center Kota Kendari yang dinilai telah mendukung pengambilan keputusan secara cepat melalui pemanfaatan teknologi informasi dan pemantauan berbasis CCTV.</p>\n\n\n\n<p>Melalui kunjungan tersebut, kedua daerah sepakat memperkuat kerja sama dan saling berbagi praktik terbaik dalam pengembangan Sistem Pemerintahan Berbasis Elektronik (SPBE), sehingga pelayanan kepada masyarakat dapat semakin cepat, transparan, dan adaptif terhadap perkembangan teknologi digital.</p>\n', '2026-07-06', 'berita/9z5mZOPEWP.webp', '5', '2026-09-23 18:16:21', '2026-10-20 01:57:59'),
('255', '65743', 'https://berita.kendarikota.go.id/kadis-kominfo-kendari-terima-mahasiswa-magister-umk-studi-tour-terkait-layanan-call-center-112/', '10', 'Kadis Kominfo Kendari Terima Mahasiswa Magister UMK Studi Tour Terkait Layanan Call Center 112', 'kadis-kominfo-kendari-terima-mahasiswa-magister-umk-studi-tour-terkait-layanan-call-center-112', '\n<p>Kendari, kendarikota.go.id– Kepala Dinas Komunikasi dan Informatika (Kominfo) Kota Kendari, Sahuriyanto Meronda, SP., MM, menerima kunjungan mahasiswa Program Magister Ilmu Pemerintahan Universitas Muhammadiyah Kendari (UMK) dalam kegiatan studi tour terkait layanan Call Center 112. Kegiatan tersebut berlangsung di Command Center Kantor Balai Kota Kendari, Kamis (18/6/2026).</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"682\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0024-1024x682.jpg\" alt class=\"wp-image-65744\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0024-1024x682.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0024-300x200.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0024-768x512.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0024-1536x1023.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0024-750x500.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0024-1140x760.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0024.jpg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Kunjungan akademik ini diikuti oleh 19 mahasiswa Magister Ilmu Pemerintahan UMK yang didampingi langsung oleh Ketua Program Studi, Andi Syaipul. Kehadiran rombongan mahasiswa bertujuan untuk mempelajari sistem pelayanan publik berbasis teknologi informasi yang diterapkan Pemerintah Kota Kendari melalui layanan darurat Call Center 112.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"682\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0033-1024x682.jpg\" alt class=\"wp-image-65745\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0033-1024x682.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0033-300x200.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0033-768x512.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0033-1536x1023.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0033-750x500.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0033-1140x760.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0033.jpg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Dalam kegiatan tersebut, Kepala Bagian Kesejahteraan Rakyat (Kabag Kesra) Kota Kendari, Dr. Sapri, bertindak sebagai moderator dan memandu jalannya diskusi. Suasana berlangsung interaktif dengan berbagai pertanyaan yang diajukan mahasiswa terkait mekanisme operasional, koordinasi antarinstansi, serta manfaat layanan Call Center 112 bagi masyarakat.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"682\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0028-1024x682.jpg\" alt class=\"wp-image-65746\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0028-1024x682.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0028-300x200.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0028-768x512.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0028-1536x1023.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0028-750x500.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0028-1140x760.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0028.jpg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Sahuriyanto Meronda menjelaskan bahwa Call Center 112 merupakan layanan pengaduan dan kedaruratan yang dapat diakses masyarakat secara gratis selama 24 jam. Layanan ini menjadi salah satu inovasi Pemerintah Kota Kendari dalam meningkatkan kualitas pelayanan publik serta mempercepat respons terhadap berbagai kondisi darurat yang terjadi di tengah masyarakat.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"682\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0026-1024x682.jpg\" alt class=\"wp-image-65747\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0026-1024x682.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0026-300x200.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0026-768x512.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0026-1536x1023.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0026-750x500.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0026-1140x760.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0026.jpg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>“Keberadaan Command Center menjadi pusat pengendalian dan pemantauan berbagai layanan digital pemerintah daerah. Melalui fasilitas tersebut, berbagai laporan masyarakat dapat diterima, diverifikasi, dan diteruskan kepada instansi terkait untuk segera ditindaklanjuti secara cepat dan tepat,” ungkapnya.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"682\" height=\"1024\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0034-682x1024.jpg\" alt class=\"wp-image-65748\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0034-682x1024.jpg 682w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0034-200x300.jpg 200w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0034-768x1153.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0034-1023x1536.jpg 1023w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0034-750x1126.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/06/IMG-20260618-WA0034.jpg 1066w\" sizes=\"(max-width: 682px) 100vw, 682px\" /></figure>\n\n\n\n<p>Para mahasiswa mendapatkan kesempatan untuk melihat secara langsung sistem kerja operator, alur penerimaan laporan, hingga proses koordinasi yang dilakukan dengan organisasi perangkat daerah maupun instansi pendukung lainnya. Kegiatan ini diharapkan dapat menambah wawasan mahasiswa mengenai implementasi tata kelola pemerintahan berbasis teknologi dan pelayanan publik modern.</p>\n\n\n\n<p>Ketua Program Studi Magister Ilmu Pemerintahan UMK, Andi Syaipul, menyampaikan apresiasi kepada Pemerintah Kota Kendari, khususnya Dinas Kominfo Kota Kendari, atas kesempatan yang diberikan kepada mahasiswa untuk belajar langsung dari praktik penyelenggaraan layanan publik. Melalui studi tour ini, mahasiswa diharapkan mampu mengintegrasikan teori yang diperoleh di bangku kuliah dengan praktik pemerintahan yang diterapkan di lapangan.</p>\n', '2026-06-18', 'berita/mPfOVgH1Wx.webp', '3', '2026-09-23 18:16:21', '2026-10-15 22:27:45'),
('257', '64504', 'https://berita.kendarikota.go.id/dinas-kominfo-kota-kendari-salurkan-bantuan-kemanusiaan-untuk-korban-banjir/', '10', 'Dinas Kominfo Kota Kendari Salurkan Bantuan Kemanusiaan untuk Korban Banjir', 'dinas-kominfo-kota-kendari-salurkan-bantuan-kemanusiaan-untuk-korban-banjir', '\n<p>Kendari, kendarikota.go.id – Dinas Komunikasi dan Informatika (Kominfo) Kota Kendari menyerahkan bantuan kemanusiaan bagi korban banjir yang terdampak di sejumlah wilayah Kota Kendari. Penyerahan bantuan tersebut dilakukan di Posko Tanggap Darurat Bencana yang berlokasi di Dinas Sosial Kota Kendari, Selasa (12/5/2026).</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/05/IMG-20260512-WA0115-1024x576.jpg\" alt class=\"wp-image-64505\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/05/IMG-20260512-WA0115-1024x576.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/05/IMG-20260512-WA0115-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/05/IMG-20260512-WA0115-768x432.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/05/IMG-20260512-WA0115-1536x864.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/05/IMG-20260512-WA0115-2048x1152.jpg 2048w, https://berita.kendarikota.go.id/wp-content/uploads/2026/05/IMG-20260512-WA0115-750x422.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/05/IMG-20260512-WA0115-1140x641.jpg 1140w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Bantuan yang disalurkan merupakan bentuk kepedulian dan solidaritas jajaran Dinas Kominfo Kota Kendari terhadap masyarakat yang terdampak bencana banjir akibat curah hujan tinggi yang melanda beberapa wilayah dalam beberapa hari terakhir. Bantuan tersebut diharapkan dapat membantu memenuhi kebutuhan dasar warga selama masa tanggap darurat.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/05/IMG-20260512-WA0119-1024x576.jpg\" alt class=\"wp-image-64506\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/05/IMG-20260512-WA0119-1024x576.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/05/IMG-20260512-WA0119-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/05/IMG-20260512-WA0119-768x432.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/05/IMG-20260512-WA0119-1536x864.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/05/IMG-20260512-WA0119-2048x1152.jpg 2048w, https://berita.kendarikota.go.id/wp-content/uploads/2026/05/IMG-20260512-WA0119-750x422.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/05/IMG-20260512-WA0119-1140x641.jpg 1140w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Kasubag Kepegawaian Dinas Kominfo Kota Kendari Nengciawati Rusmin mengatakan, bantuan yang diberikan terdiri dari berbagai kebutuhan pokok seperti beras, mie instan, air mineral, telur, serta sejumlah kebutuhan harian lainnya. Bantuan tersebut dikumpulkan melalui partisipasi seluruh pegawai lingkup Dinas Kominfo Kota Kendari.</p>\n\n\n\n<p>Menurutnya, penyaluran bantuan ini merupakan bagian dari komitmen Pemerintah Kota Kendari dalam memberikan perhatian kepada masyarakat yang tengah menghadapi musibah. Selain dukungan logistik, pemerintah juga terus melakukan koordinasi lintas OPD untuk memastikan penanganan bencana berjalan optimal.</p>\n\n\n\n<p>“Semoga bantuan yang kami salurkan ini dapat meringankan beban masyarakat yang terdampak banjir. Ini adalah bentuk empati dan kebersamaan kita dalam menghadapi musibah,” ujarnya.</p>\n\n\n\n<p>Sementara itu, pihak Posko Tanggap Darurat Bencana Dinas Sosial Kota Kendari menyampaikan apresiasi atas dukungan dan kepedulian dari Dinas Kominfo Kota Kendari. Bantuan yang diterima selanjutnya akan didistribusikan kepada warga terdampak di sejumlah titik banjir sesuai data dan kebutuhan di lapangan.</p>\n\n\n\n<p>Pemerintah Kota Kendari juga mengimbau masyarakat agar tetap waspada terhadap potensi cuaca ekstrem yang masih dapat terjadi. Selain itu, warga diminta menjaga kesehatan dan keselamatan, serta mengikuti arahan petugas demi meminimalisir risiko selama masa penanganan bencana berlangsung.</p>\n', '2026-05-12', 'berita/LsmRKERTFH.webp', '3', '2026-09-23 18:16:21', '2026-10-12 09:27:25'),
('258', '63503', 'https://berita.kendarikota.go.id/kominfo-kendari-terima-kunjungan-kominfo-konawe-perkuat-integrasi-layanan-call-center-112/', '10', 'Kominfo Kendari Terima Kunjungan Kominfo Konawe, Perkuat Integrasi Layanan Call Center 112', 'kominfo-kendari-terima-kunjungan-kominfo-konawe-perkuat-integrasi-layanan-call-center-112', '\n<p>Kendari, kendarikota.go.id – Kepala Dinas Komunikasi dan Informatika Kota Kendari, Sahuriyanto Meronda, menerima kunjungan kerja Kepala Dinas Kominfo Kabupaten Konawe, Muh. Akib Ras, di Command Center Balai Kota Kendari pada Jumat (17/4/2026). Kunjungan ini menjadi bagian dari upaya memperkuat koordinasi antar daerah dalam pengembangan layanan pemerintahan berbasis teknologi informasi.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0400-1024x576.jpg\" alt class=\"wp-image-63504\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0400-1024x576.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0400-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0400-768x432.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0400-750x422.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0400-1140x641.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0400.jpg 1280w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Pertemuan tersebut difokuskan pada pembahasan penguatan layanan Call Center 112 yang telah berjalan di Kota Kendari. Layanan ini merupakan salah satu inovasi Pemkot Kendari dalam memberikan respon cepat terhadap aduan masyarakat, khususnya dalam kondisi darurat.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0396-1024x576.jpg\" alt class=\"wp-image-63505\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0396-1024x576.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0396-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0396-768x432.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0396-750x422.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0396-1140x641.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0396.jpg 1280w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Dalam pemaparannya, dijelaskan bahwa sistem Call Center 112 di Kendari telah terintegrasi dengan Command Center serta jaringan CCTV pemantauan kota. Setiap laporan yang masuk langsung dibuatkan tiket aduan dan diteruskan kepada Organisasi Perangkat Daerah (OPD) teknis sesuai jenis permasalahan yang dilaporkan.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0399-1024x576.jpg\" alt class=\"wp-image-63506\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0399-1024x576.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0399-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0399-768x432.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0399-750x422.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0399-1140x641.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0399.jpg 1280w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Seluruh proses penanganan laporan dapat dipantau secara real-time melalui dashboard monitoring di Command Center. Sistem ini memungkinkan pengawasan progres penyelesaian aduan secara transparan dan terukur oleh masing-masing OPD terkait.</p>\n\n\n\n<p>Namun demikian, dalam evaluasi pelaksanaan layanan masih ditemukan sejumlah kendala. Di antaranya keterlambatan respon dari OPD teknis serta masih adanya laporan masyarakat yang disampaikan melalui kanal tidak resmi sehingga tidak tercatat dalam sistem tiket.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0397-1024x576.jpg\" alt class=\"wp-image-63507\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0397-1024x576.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0397-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0397-768x432.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0397-750x422.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0397-1140x641.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0397.jpg 1280w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Dari data evaluasi, tercatat sebanyak 256 panggilan masuk, dengan 60 panggilan yang belum terlayani secara optimal. Selain itu, sekitar 18 persen laporan tidak sesuai dengan kanal pelaporan yang telah ditetapkan, sehingga menjadi perhatian dalam peningkatan efektivitas layanan.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0398-1024x576.jpg\" alt class=\"wp-image-63508\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0398-1024x576.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0398-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0398-768x432.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0398-750x422.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0398-1140x641.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260417-WA0398.jpg 1280w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Kedua pihak sepakat bahwa penguatan standar operasional prosedur (SOP) respon cepat, peningkatan disiplin OPD, serta edukasi kepada masyarakat terkait penggunaan kanal resmi menjadi langkah penting ke depan. Melalui kunjungan ini, Kominfo Konawe juga menyatakan kesiapan untuk mereplikasi sistem Command Center Kendari sebagai upaya peningkatan kualitas layanan publik di daerahnya.</p>\n', '2026-04-17', 'berita/fIWr9vG5y7.webp', '4', '2026-09-23 18:16:21', '2026-10-15 17:52:39'),
('259', '64697', 'https://berita.kendarikota.go.id/layanan-call-center-112-kendari-gangguan-dinas-kominfo-minta-maaf-ke-masyarakat/', '10', 'Layanan Call Center 112 Kendari Gangguan, Dinas Kominfo Minta Maaf ke Masyarakat', 'layanan-call-center-112-kendari-gangguan-dinas-kominfo-minta-maaf-ke-masyarakat', '\n<p>Kendari, kendarikota.go.id – Layanan panggilan darurat 112 milik Pemerintah Kota Kendari dilaporkan mengalami gangguan sejak Sabtu (16/5/2026) malam. Kondisi tersebut membuat sebagian masyarakat kesulitan mengakses layanan pengaduan dan panggilan darurat yang selama ini digunakan untuk kebutuhan cepat di tengah situasi tertentu.</p>\n\n\n\n<p>Kepala Dinas Komunikasi dan Informatika Kota Kendari, Sahuriyanto Meronda, menyampaikan permohonan maaf kepada masyarakat atas terganggunya layanan tersebut.</p>\n\n\n\n<p>“Kami mohon maaf atas gangguan layanan 112, kami sedang mengupayakan untuk perbaikan,” ungkapnya, Minggu (17/5/2026).</p>\n\n\n\n<p>Menurutnya, Pemerintah Kota Kendari melalui tim teknis Dinas Kominfo saat ini masih melakukan pemeriksaan sistem untuk mengetahui penyebab gangguan yang terjadi pada layanan 112.</p>\n\n\n\n<p>Sementara itu, Kepala Bidang E-Government Dinas Kominfo Kota Kendari, Herry, menjelaskan layanan sebenarnya masih aktif, namun tidak berjalan normal saat diakses masyarakat.</p>\n\n\n\n<p>“Kalau menelpon terhubung tapi tidak bisa tembus atau tidak nyambung,” ujarnya.</p>\n\n\n\n<p>Gangguan tersebut menyebabkan panggilan yang masuk tidak dapat tersambung secara maksimal ke sistem layanan operator 112.</p>\n\n\n\n<p>Saat ini, tim teknis Dinas Kominfo Kota Kendari masih terus melakukan pengecekan terhadap jaringan dan sistem layanan guna memastikan gangguan dapat segera diatasi.</p>\n\n\n\n<p>Pemerintah Kota Kendari memastikan upaya perbaikan terus dilakukan agar layanan darurat tersebut dapat kembali berfungsi normal secepatnya.</p>\n\n\n\n<p>Layanan 112 sendiri merupakan call center darurat yang digunakan masyarakat untuk melaporkan berbagai kondisi kedaruratan, mulai dari kebakaran, kecelakaan, bencana, gangguan keamanan hingga situasi mendesak lainnya.</p>\n\n\n\n<p>Karena itu, gangguan layanan tersebut menjadi perhatian pemerintah daerah mengingat pentingnya akses cepat masyarakat terhadap layanan darurat, terutama di tengah situasi cuaca ekstrem dan meningkatnya kebutuhan penanganan cepat di lapangan.</p>\n\n\n\n<p>Dinas Kominfo Kota Kendari juga mengimbau masyarakat untuk tetap tenang sembari menunggu proses normalisasi sistem selesai dilakukan oleh tim teknis.</p>\n\n\n\n<p>Pemerintah berharap layanan 112 dapat segera kembali beroperasi secara optimal sehingga masyarakat kembali dapat mengakses layanan kedaruratan tanpa kendala.</p>\n', '2026-05-17', 'berita/1PpV5rgAAk.webp', '4', '2026-09-23 22:19:53', '2026-10-17 23:10:49'),
('260', '63413', 'https://berita.kendarikota.go.id/kadis-kominfo-kendari-terima-kunjungan-kadis-kominfo-bombana-bahas-penguatan-layanan-call-center-112-terintegrasi/', '10', 'Kadis Kominfo Kendari Terima Kunjungan Kadis Kominfo Bombana, Bahas Penguatan Layanan Call Center 112 Terintegrasi', 'kadis-kominfo-kendari-terima-kunjungan-kadis-kominfo-bombana-bahas-penguatan-layanan-call-center-112-terintegrasi', '\n<p>Kendari, kendarikota.go.id – Kepala Dinas Komunikasi dan Informatika (Kominfo) Kota Kendari Sahuriyanto Meronda menerima kunjungan Kepala Dinas Kominfo Kabupaten Bombana Muhammad Siarah dalam rangka studi koordinasi terkait pengembangan layanan terintegrasi di lingkungan Pemerintah Kota Kendari. Pertemuan tersebut berlangsung di Command Center Kantor Balai Kota Kendari, Rabu (15/4/2026).</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-8 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"768\" height=\"1024\" data-id=\"63421\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/c1eade0e-63ae-407f-9398-9da474b5aa3b-1-768x1024.jpeg\" alt class=\"wp-image-63421\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/c1eade0e-63ae-407f-9398-9da474b5aa3b-1-768x1024.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/c1eade0e-63ae-407f-9398-9da474b5aa3b-1-225x300.jpeg 225w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/c1eade0e-63ae-407f-9398-9da474b5aa3b-1-750x1000.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/c1eade0e-63ae-407f-9398-9da474b5aa3b-1.jpeg 960w\" sizes=\"(max-width: 768px) 100vw, 768px\" /></figure>\n</figure>\n\n\n\n<p>Kunjungan ini bertujuan untuk mempelajari secara langsung implementasi sistem layanan publik berbasis teknologi, khususnya pengelolaan Call Center 112 yang telah diterapkan di Kota Kendari. Layanan tersebut dinilai efektif dalam memberikan respons cepat terhadap berbagai kondisi darurat yang dialami masyarakat.</p>\n\n\n\n<p>Kadis Kominfo Kota Kendari Sahuriyanto Meronda, dalam sambutannya menyampaikan bahwa keberadaan Call Center 112 merupakan salah satu bentuk komitmen pemerintah dalam meningkatkan kualitas pelayanan publik. Sistem ini mengintegrasikan berbagai instansi terkait seperti kepolisian, pemadam kebakaran, layanan kesehatan, hingga instansi teknis lainnya dalam satu pusat kendali.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-9 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"768\" height=\"1024\" data-id=\"63422\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/eb148cb5-a7a7-4f3b-9d93-5c6884367260-768x1024.jpeg\" alt class=\"wp-image-63422\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/eb148cb5-a7a7-4f3b-9d93-5c6884367260-768x1024.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/eb148cb5-a7a7-4f3b-9d93-5c6884367260-225x300.jpeg 225w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/eb148cb5-a7a7-4f3b-9d93-5c6884367260-750x1000.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/eb148cb5-a7a7-4f3b-9d93-5c6884367260.jpeg 960w\" sizes=\"(max-width: 768px) 100vw, 768px\" /></figure>\n</figure>\n\n\n\n<p>“Command Center menjadi pusat pemantauan sekaligus pengendalian berbagai layanan berbasis digital di Kota Kendari,” katanya.</p>\n\n\n\n<p>Dengan dukungan teknologi yang memadai, setiap laporan masyarakat dapat ditindaklanjuti secara cepat, tepat, dan terkoordinasi.</p>\n\n\n\n<p>Sementara itu, Kadis Kominfo Bombana Muhammad Siarah mengapresiasi sistem yang telah dibangun oleh Pemerintah Kota Kendari.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-10 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"768\" height=\"1024\" data-id=\"63423\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/b91e32ea-56bd-47b7-afd8-0db45fdd03d2-768x1024.jpeg\" alt class=\"wp-image-63423\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/b91e32ea-56bd-47b7-afd8-0db45fdd03d2-768x1024.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/b91e32ea-56bd-47b7-afd8-0db45fdd03d2-225x300.jpeg 225w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/b91e32ea-56bd-47b7-afd8-0db45fdd03d2-750x1000.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/b91e32ea-56bd-47b7-afd8-0db45fdd03d2.jpeg 960w\" sizes=\"(max-width: 768px) 100vw, 768px\" /></figure>\n</figure>\n\n\n\n<p>“Kunjungan ini menjadi referensi penting bagi kami dalam mengembangkan sistem layanan serupa di Kabupaten Bombana, khususnya dalam hal integrasi lintas sektor,” ungkapnya.</p>\n\n\n\n<p>Selain diskusi teknis, rombongan juga melakukan peninjauan langsung terhadap fasilitas Command Center, termasuk sistem pemantauan CCTV dan mekanisme kerja operator Call Center 112. Hal ini memberikan gambaran nyata mengenai alur kerja layanan darurat yang terintegrasi.</p>\n\n\n\n<p>Melalui kunjungan ini, diharapkan terjalin sinergi antar pemerintah daerah dalam meningkatkan pelayanan publik berbasis teknologi. Pemerintah Kota Kendari pun terus berkomitmen untuk berbagi pengalaman dan inovasi guna mendorong peningkatan kualitas layanan di daerah lain.</p>\n', '2026-04-15', 'berita/btrAOftYTG.webp', '3', '2026-09-23 23:15:04', '2026-10-16 00:05:58'),
('261', '63339', 'https://berita.kendarikota.go.id/diskominfo-kendari-edukasi-peserta-persami-kkri-kodim-1417-tentang-bijak-bermedia-sosial/', '10', 'Diskominfo Kendari Edukasi Peserta Persami KKRI Kodim 1417 tentang Bijak Bermedia Sosial', 'diskominfo-kendari-edukasi-peserta-persami-kkri-kodim-1417-tentang-bijak-bermedia-sosial', '\n<p>Kendari, kendarikota.go.id — Pemerintah Kota Kendari melalui Dinas Komunikasi dan Informatika (Diskominfo) memberikan bimbingan bertema “Bijak dalam Bersosial Media” kepada peserta Perkemahan Sabtu Minggu (Persami) Korps Kadet Republik Indonesia (KKRI) Gelombang IV Triwulan I Tahun 2026. Kegiatan yang digelar oleh Kodim 1417/Kendari ini berlangsung di Pantai Nambo, Minggu (12/04/2026).</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260413-WA0295-1024x576.jpg\" alt class=\"wp-image-63340\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260413-WA0295-1024x576.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260413-WA0295-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260413-WA0295-768x432.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260413-WA0295-1536x864.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260413-WA0295-2048x1153.jpg 2048w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260413-WA0295-750x422.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260413-WA0295-1140x642.jpg 1140w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Sekretaris Dinas Kominfo Kota Kendari, Wawan Astanto, menjelaskan bahwa bijak dalam bermedia sosial berarti menggunakan akal sehat dalam memilah konten, menjaga privasi, serta menjunjung tinggi etika dalam berinteraksi di ruang digital. Ia menekankan pentingnya membangun komunikasi yang positif agar tercipta lingkungan pergaulan yang sehat di dunia maya.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"683\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260414-WA0022-1024x683.jpg\" alt class=\"wp-image-63341\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260414-WA0022-1024x683.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260414-WA0022-300x200.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260414-WA0022-768x512.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260414-WA0022-750x500.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260414-WA0022-1140x760.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260414-WA0022.jpg 1224w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Lebih lanjut, Wawan mengingatkan peserta untuk selalu menyaring informasi sebelum membagikannya guna menghindari penyebaran hoaks. Selain itu, peserta juga diimbau menjaga sopan santun, melindungi data pribadi seperti kata sandi dan lokasi, serta membatasi waktu penggunaan media sosial demi menjaga kesehatan mental.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"683\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260413-WA0279-1024x683.jpg\" alt class=\"wp-image-63342\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260413-WA0279-1024x683.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260413-WA0279-300x200.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260413-WA0279-768x512.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260413-WA0279-1536x1024.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260413-WA0279-2048x1365.jpg 2048w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260413-WA0279-750x500.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260413-WA0279-1140x760.jpg 1140w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Di tempat yang sama, Pasiter Kodim 1417/Kendari, Mayor Inf. Djanwar B. Mantaung, menyampaikan bahwa kegiatan ini merupakan bagian dari program nasional yang diinisiasi oleh Presiden dan dilaksanakan melalui jajaran TNI. Program Persami KKRI bertujuan membentuk karakter generasi muda agar memiliki jiwa nasionalisme, kedisiplinan, serta kepribadian yang kuat.</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img loading=\"lazy\" decoding=\"async\" width=\"720\" height=\"925\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260413-WA0280.jpg\" alt class=\"wp-image-63343\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260413-WA0280.jpg 720w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260413-WA0280-234x300.jpg 234w\" sizes=\"(max-width: 720px) 100vw, 720px\" /></figure>\n\n\n\n<p>Ia menambahkan, kegiatan Persami KKRI ini merupakan yang pertama kali dilaksanakan di wilayah Kodim 1417/Kendari, setelah sebelumnya kegiatan serupa dilakukan dalam bentuk Persami Pramuka. Diharapkan melalui kegiatan ini para peserta dapat memperoleh pengalaman dan pembelajaran yang bermanfaat sebagai bekal di masa depan.</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img loading=\"lazy\" decoding=\"async\" width=\"668\" height=\"989\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260413-WA0283.jpg\" alt class=\"wp-image-63344\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260413-WA0283.jpg 668w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260413-WA0283-203x300.jpg 203w\" sizes=\"(max-width: 668px) 100vw, 668px\" /></figure>\n\n\n\n<p>Salah satu peserta dari SMAN 4 Kendari, Zahra, mengungkapkan bahwa kegiatan tersebut sangat bermanfaat karena memberikan banyak pengetahuan sekaligus kesempatan untuk bersosialisasi dengan peserta dari sekolah lain. Ia berharap kegiatan serupa dapat terus dilaksanakan untuk generasi berikutnya.</p>\n\n\n\n<p>Hal senada disampaikan peserta lainnya, Muh. Nabil Syirad dari SMAN 2 Konawe Selatan dan Rafa dari SMKN 3 Kendari. Mereka menilai kegiatan ini mampu membentuk karakter disiplin, mempererat kebersamaan, serta meningkatkan kepercayaan diri dan jiwa kepemimpinan. Diketahui, kegiatan Persami KKRI ini berlangsung sejak 10 hingga 12 April 2026 dan diikuti oleh puluhan peserta dari SMA/SMK se-Sulawesi Tenggara.</p>\n', '2026-04-14', 'berita/e2j6KmBmUy.webp', '3', '2026-09-23 23:15:04', '2026-10-15 09:29:17'),
('262', '63246', 'https://berita.kendarikota.go.id/gerak-cepat-pemkot-kendari-tangani-genangan-di-area-perkantoran-kominfo-sultra/', '10', 'Gerak Cepat Pemkot Kendari Tangani Genangan di Area Perkantoran Kominfo Sultra', 'gerak-cepat-pemkot-kendari-tangani-genangan-di-area-perkantoran-kominfo-sultra', '\n<p>Kendari, kendarikota.go.id – Pemerintah Kota Kendari bergerak cepat menangani genangan banjir yang terjadi di kawasan perkantoran Dinas Komunikasi dan Informatika Provinsi Sulawesi Tenggara akibat saluran drainase yang tersumbat, Jumat (10/4/2026). Penanganan ini dilakukan sebagai respons cepat terhadap gangguan fungsi infrastruktur perkotaan di kawasan pelayanan publik.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"768\" height=\"1024\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260410-WA0130-768x1024.jpg\" alt class=\"wp-image-63247\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260410-WA0130-768x1024.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260410-WA0130-225x300.jpg 225w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260410-WA0130-1152x1536.jpg 1152w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260410-WA0130-1536x2048.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260410-WA0130-750x1000.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260410-WA0130-1140x1520.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260410-WA0130-scaled.jpg 1920w\" sizes=\"(max-width: 768px) 100vw, 768px\" /></figure>\n\n\n\n<p>Genangan air terjadi setelah material sisa tebangan dan pangkasan pohon menutup aliran drainase, sehingga air tidak dapat mengalir secara optimal saat hujan turun. Kondisi tersebut menyebabkan air meluap dan menggenangi area perkantoran.</p>\n\n\n\n<p>Proses penanganan melibatkan tim gabungan lintas organisasi perangkat daerah (OPD) dan dipantau langsung oleh Sekretaris Daerah Kota Kendari Amir Hasan. Turut hadir Asisten III Setda Kota Kendari sekaligus Kasatgas Penataan Kota La Ode Manas Salihin, Kepala Dinas Lingkungan Hidup dan Kehutanan Kota Kendari Erlis Sadya, serta sejumlah pejabat terkait lainnya.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"768\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260410-WA0123-1024x768.jpg\" alt class=\"wp-image-63248\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260410-WA0123-1024x768.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260410-WA0123-300x225.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260410-WA0123-768x576.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260410-WA0123-1536x1152.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260410-WA0123-750x563.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260410-WA0123-1140x855.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260410-WA0123.jpg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Kepala Dinas Komunikasi dan Informatika Kota Kendari, Sahuriyanto Meronda, menyampaikan bahwa pemerintah kota segera mengambil langkah cepat setelah menerima laporan adanya genangan di lokasi tersebut. Tim langsung diturunkan untuk mengidentifikasi penyebab dan melakukan penanganan di lapangan.</p>\n\n\n\n<p>“Setelah kami identifikasi, penyebab utama genangan adalah sisa tebangan dan pangkasan pohon yang menutup drainase. Karena itu tim langsung diturunkan untuk melakukan pembersihan agar aliran air kembali normal,” ujarnya di lokasi kegiatan.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"768\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260410-WA0127-1024x768.jpg\" alt class=\"wp-image-63249\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260410-WA0127-1024x768.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260410-WA0127-300x225.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260410-WA0127-768x576.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260410-WA0127-1536x1152.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260410-WA0127-750x563.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260410-WA0127-1140x855.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/04/IMG-20260410-WA0127.jpg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Petugas gabungan kemudian melakukan pengangkatan batang dan ranting pohon yang menghalangi saluran air dengan menggunakan peralatan kebersihan serta kendaraan operasional milik Dinas Lingkungan Hidup dan Kehutanan Kota Kendari. Upaya ini dilakukan secara cepat dan terkoordinasi guna mempercepat normalisasi aliran air.</p>\n\n\n\n<p>Setelah proses pembersihan dilakukan, aliran air di lokasi kembali lancar dan genangan berangsur surut. Pemerintah Kota Kendari juga mengimbau masyarakat dan seluruh pihak agar tidak membuang sisa pemangkasan pohon maupun sampah ke dalam drainase, demi menjaga fungsi saluran air dan mencegah terjadinya banjir di kemudian hari.</p>\n', '2026-04-10', 'berita/urVNYJJn1M.webp', '3', '2026-09-23 23:15:04', '2026-10-21 06:28:37'),
('263', '62450', 'https://berita.kendarikota.go.id/diskominfo-kendari-terima-kunjungan-diskominfo-konawe-selatan-bahas-pengelolaan-layanan-call-center-112/', '10', 'Diskominfo Kendari Terima Kunjungan Diskominfo Konawe Selatan, Bahas Pengelolaan Layanan Call Center 112', 'diskominfo-kendari-terima-kunjungan-diskominfo-konawe-selatan-bahas-pengelolaan-layanan-call-center-112', '\n<p>Kendari, kendarikota.go.id – Kepala Dinas Komunikasi dan Informatika (Diskominfo) Kota Kendari Sahuriyanto Meronda, SP.,MM menerima kunjungan kerja dari Dinas Komunikasi dan Informatika Kabupaten Konawe Selatan dalam rangka koordinasi terkait pengelolaan layanan Call Center 112. Kunjungan ini berlangsung di kantor Diskominfo Kota Kendari dan disambut langsung oleh jajaran pejabat serta staf pengelola layanan kedaruratan tersebut, Senin (9/3/2026).</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"735\" height=\"1024\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260309-WA0092-735x1024.jpg\" alt class=\"wp-image-62453\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260309-WA0092-735x1024.jpg 735w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260309-WA0092-215x300.jpg 215w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260309-WA0092-768x1070.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260309-WA0092-750x1045.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260309-WA0092.jpg 919w\" sizes=\"(max-width: 735px) 100vw, 735px\" /></figure>\n\n\n\n<p>Kunjungan ini bertujuan untuk mempelajari secara langsung sistem pengelolaan layanan Call Center 112 yang telah diterapkan Pemerintah Kota Kendari sebagai salah satu layanan pengaduan dan respon cepat bagi masyarakat. Selain itu, Diskominfo Konawe Selatan juga ingin melihat mekanisme operasional, sistem kerja petugas, serta integrasi layanan dengan berbagai instansi terkait<br />‎<br />‎Dalam kesempatan tersebut, perwakilan Diskominfo Kota Kendari memaparkan berbagai aspek teknis pengelolaan Call Center 112, mulai dari sistem penerimaan laporan masyarakat, prosedur verifikasi informasi, hingga proses koordinasi dengan Organisasi Perangkat Daerah (OPD) maupun instansi terkait seperti pemadam kebakaran, kepolisian, dan layanan kesehatan.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260309-WA0075-1024x576.jpg\" alt class=\"wp-image-62454\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260309-WA0075-1024x576.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260309-WA0075-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260309-WA0075-768x432.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260309-WA0075-750x422.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260309-WA0075-1140x641.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260309-WA0075.jpg 1280w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>‎Kepala Dinas Kominfo Kota Kendari, Sahuriyanto Meronda, mengatakan Pemerintah Kota Kendari terbuka untuk berbagi pengalaman dengan daerah lain dalam pengelolaan layanan kedaruratan berbasis teknologi.<br />‎<br />‎“Layanan Call Center 112 ini kami rancang sebagai sistem respon cepat yang dapat diakses masyarakat selama 24 jam. Kami senang jika pengalaman yang kami miliki bisa menjadi referensi bagi daerah lain dalam meningkatkan pelayanan publik,” ujar Sahuriyanto.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260309-WA0082-1024x576.jpg\" alt class=\"wp-image-62455\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260309-WA0082-1024x576.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260309-WA0082-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260309-WA0082-768x432.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260309-WA0082-1536x864.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260309-WA0082-2048x1152.jpg 2048w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260309-WA0082-750x422.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260309-WA0082-1140x641.jpg 1140w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>‎Ia juga menambahkan bahwa keberhasilan layanan tersebut tidak hanya bergantung pada teknologi, tetapi juga pada koordinasi yang baik antarinstansi yang terlibat dalam penanganan laporan masyarakat.<br />‎<br />‎“Yang paling penting adalah kolaborasi antar OPD dan instansi terkait seperti pemadam kebakaran, kepolisian, dan layanan kesehatan sehingga setiap laporan masyarakat bisa segera ditindaklanjuti,” tambahnya.<br />‎<br />‎Selain itu, Kepala Dinas Kominfo Konawe Selatan Anas Mas’ud bersama rombongan, juga diajak melihat langsung ruang operasional Call Center 112 Kota Kendari. Mereka menyaksikan bagaimana petugas call taker menerima laporan masyarakat selama 24 jam serta proses dispatch atau penerusan laporan kepada instansi yang berwenang untuk segera ditindaklanjuti.<br />‎<br />‎Pihak Diskominfo Konawe Selatan mengapresiasi pengelolaan layanan Call Center 112 di Kota Kendari yang dinilai telah berjalan dengan baik dan responsif dalam menangani berbagai laporan kedaruratan masyarakat. Sistem yang terintegrasi dan dukungan sumber daya manusia dinilai menjadi faktor penting dalam keberhasilan layanan tersebut.<br />‎<br />‎Kepala Dinas Kominfo Kabupaten Konawe Selatan, Drs. Annas Mas’ud, M.Si, mengapresiasi sistem pengelolaan Call Center 112 di Kota Kendari yang dinilai sudah berjalan dengan baik dan responsif.<br />‎<br />‎“Kami melihat pengelolaan layanan Call Center 112 di Kota Kendari sudah cukup baik, baik dari sisi sistem, operasional, maupun koordinasi dengan instansi terkait. Ini menjadi referensi penting bagi kami untuk mengembangkan layanan serupa di Konawe Selatan,” kata Anas.<br />‎<br />‎Ia berharap kunjungan tersebut dapat memberikan gambaran teknis yang lebih jelas dalam menyiapkan layanan pengaduan kedaruratan di daerahnya.<br />‎<br />‎“Melalui kunjungan ini kami mendapatkan banyak informasi dan pengalaman yang sangat bermanfaat sebagai bahan pengembangan layanan berbasis teknologi di Konawe Selatan,” ujarnya.<br />‎<br />‎Melalui kunjungan ini, diharapkan Diskominfo Konawe Selatan dapat mengadopsi berbagai praktik baik yang diterapkan di Kota Kendari dalam mengembangkan layanan serupa di daerahnya. Hal ini sejalan dengan upaya pemerintah daerah dalam meningkatkan kualitas pelayanan publik berbasis teknologi informasi.<br />‎<br />‎Pemerintah Kota Kendari melalui Diskominfo menyambut baik kunjungan tersebut sebagai bagian dari upaya memperkuat sinergi antar daerah dalam pengembangan layanan digital pemerintahan. Diharapkan kolaborasi dan pertukaran informasi seperti ini dapat terus dilakukan guna meningkatkan pelayanan kepada masyarakat secara lebih cepat, efektif, dan responsif.</p>\n', '2026-03-09', 'berita/UBdjKtu4w3.webp', '2', '2026-09-23 23:15:04', '2026-09-26 12:30:00'),
('264', '62440', 'https://berita.kendarikota.go.id/diskominfo-kendari-dukung-pembatasan-akun-media-sosial-di-bawah-usia-16-tahun/', '10', 'Diskominfo Kendari Dukung Pembatasan Akun Media Sosial di Bawah Usia 16 Tahun', 'diskominfo-kendari-dukung-pembatasan-akun-media-sosial-di-bawah-usia-16-tahun', '\n<p>Kendari, kendarikota.go.id – Pemerintah Kota Kendari melalui Diskominfo menyatakan dukungan terhadap kebijakan pemerintah pusat terkait pembatasan kepemilikan akun digital bagi anak di bawah usia 16 tahun pada sejumlah platform media sosial, Minggu (8/3/2026)</p>\n\n\n\n<p>Kebijakan tersebut tertuang dalam Peraturan Menteri Nomor 9 Tahun 2026 yang merupakan turunan dari Peraturan Pemerintah tentang perlindungan anak di ruang digital. Aturan ini mulai diimplementasikan secara bertahap mulai 28 Maret 2026.</p>\n\n\n\n<p>Kepala Dinas Komunikasi dan Informatika Kota Kendari, Sahuriyanto Meronda, mengatakan bahwa kebijakan tersebut merupakan langkah penting untuk melindungi generasi muda dari berbagai dampak negatif penggunaan media sosial yang tidak terkontrol.</p>\n\n\n\n<p>Menurutnya, perkembangan teknologi digital yang sangat pesat harus diimbangi dengan kebijakan yang mampu memberikan perlindungan bagi anak-anak, khususnya dalam penggunaan internet dan media sosial.</p>\n\n\n\n<p>Ia menjelaskan bahwa anak-anak di bawah usia 16 tahun dinilai masih membutuhkan pengawasan orang tua dalam mengakses berbagai platform digital agar tidak terpapar konten yang tidak sesuai dengan usia mereka.</p>\n\n\n\n<p>“Pembatasan ini bukan untuk menghalangi anak-anak mengenal teknologi, tetapi untuk memastikan mereka menggunakan teknologi secara sehat, aman, dan sesuai dengan tahap perkembangan mereka,” ujar Sahuriyanto.</p>\n\n\n\n<p>Lebih lanjut, ia menambahkan bahwa media sosial memiliki banyak manfaat apabila digunakan secara bijak, seperti untuk belajar, berkomunikasi, dan mengembangkan kreativitas.</p>\n\n\n\n<p>Namun di sisi lain, tanpa pengawasan yang tepat, media sosial juga dapat membawa dampak negatif seperti kecanduan gawai, perundungan siber (cyber bullying), hingga paparan konten yang tidak layak.</p>\n\n\n\n<p>Oleh karena itu, Diskominfo Kota Kendari mendukung penuh kebijakan pembatasan tersebut sebagai bentuk perlindungan terhadap anak-anak di ruang digital.</p>\n\n\n\n<p>Sahuriyanto juga menekankan pentingnya peran orang tua dalam mengawasi aktivitas digital anak-anak di rumah. Orang tua harus menjadi pendamping utama dalam mengenalkan penggunaan teknologi kepada anak, termasuk memberikan pemahaman mengenai etika berinternet dan bahaya penyalahgunaan media sosial.</p>\n\n\n\n<p>Selain itu, pihak sekolah juga diharapkan dapat berperan aktif memberikan edukasi literasi digital kepada para siswa agar mereka memahami cara menggunakan teknologi secara bijak.</p>\n\n\n\n<p>Diskominfo Kota Kendari sendiri terus melakukan berbagai program literasi digital kepada masyarakat guna meningkatkan kesadaran tentang penggunaan internet yang sehat dan produktif.</p>\n\n\n\n<p>Program tersebut menyasar berbagai kalangan, mulai dari pelajar, guru, hingga masyarakat umum. Melalui literasi digital, masyarakat diharapkan mampu memanfaatkan teknologi informasi secara positif dan terhindar dari berbagai risiko di dunia maya.</p>\n\n\n\n<p>Kadis Kominfo menegaskan bahwa, kebijakan pembatasan usia ini juga menjadi momentum untuk memperkuat edukasi digital kepada generasi muda.</p>\n\n\n\n<p>Dengan adanya regulasi ini, diharapkan anak-anak dapat tumbuh dan berkembang dengan lebih sehat, baik secara mental maupun sosial.Generasi muda adalah aset masa depan bangsa. Karena itu, perlindungan mereka di ruang digital harus menjadi perhatian bersama.</p>\n', '2026-03-09', 'berita/SOsqbBqJvh.webp', '4', '2026-09-23 23:15:04', '2026-10-17 04:39:08'),
('265', '62407', 'https://berita.kendarikota.go.id/kadis-kominfo-kendari-dampingi-anak-asuh-stunting-di-kelurahan-benu-benua/', '10', 'Kadis Kominfo Kendari Dampingi Anak Asuh Stunting di Kelurahan Benu-benua', 'kadis-kominfo-kendari-dampingi-anak-asuh-stunting-di-kelurahan-benu-benua', '\n<p>Kendari, kendarikota.go.id – Kepala Dinas Komunikasi dan Informatika (Kominfo) Kota Kendari, Sahuriyanto meronda melakukan pendampingan terhadap anak asuh stunting di , jl.P. Diponegoro. RT.001/RW.001 Kelurahan Benu-benua, Kecamatan Kendari Barat Kamis,05/03/2026.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260306-WA0063-1024x576.jpg\" alt class=\"wp-image-62409\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260306-WA0063-1024x576.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260306-WA0063-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260306-WA0063-768x432.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260306-WA0063-1536x864.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260306-WA0063-750x422.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260306-WA0063-1140x641.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260306-WA0063.jpg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>“Kegiatan ini merupakan bagian dari upaya Pemerintah Kota Kendari dalam percepatan penanganan stunting,” katanya.</p>\n\n\n\n<p>Pendampingan tersebut dilakukan dengan mengunjungi langsung rumah keluarga anak asuh stunting Muh.Arfah. Kunjungan ini bertujuan untuk memastikan kondisi kesehatan serta perkembangan anak agar dapat tumbuh dengan baik.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260306-WA0059-1024x576.jpg\" alt class=\"wp-image-62410\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260306-WA0059-1024x576.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260306-WA0059-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260306-WA0059-768x432.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260306-WA0059-1536x864.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260306-WA0059-750x422.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260306-WA0059-1140x641.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260306-WA0059.jpg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Dalam kunjungannya, Kadis Kominfo Sahuriyanto berdialog langsung dengan orang tua anak guna mengetahui kondisi kesehatan, pola asuh, serta pemenuhan gizi anak sehari-hari. Hal ini penting untuk memastikan anak mendapatkan perhatian dan asupan gizi yang cukup.</p>\n\n\n\n<p>Kadis Kominfo mengatakan bahwa program anak asuh stunting merupakan salah satu langkah nyata pemerintah dalam menekan angka stunting di Kota Kendari. Melalui pendampingan langsung, diharapkan setiap anak yang menjadi sasaran program dapat dipantau secara berkala.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260306-WA0058-1024x576.jpg\" alt class=\"wp-image-62411\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260306-WA0058-1024x576.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260306-WA0058-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260306-WA0058-768x432.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260306-WA0058-1536x864.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260306-WA0058-750x422.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260306-WA0058-1140x641.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260306-WA0058.jpg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Menurutnya, peran orang tua sangat penting dalam mendukung tumbuh kembang anak, terutama dalam memastikan pola makan yang sehat dan bergizi.</p>\n\n\n\n<p>Ia juga mengimbau agar orang tua rutin memeriksakan kesehatan anak di fasilitas pelayanan kesehatan terdekat. Selain melakukan pemantauan kondisi anak, dalam kesempatan tersebut juga diserahkan bantuan berupa makanan tambahan bergizi yang diharapkan dapat membantu memenuhi kebutuhan nutrisi anak.</p>\n\n\n\n<p>Mantan Kadis Pertanian ini, menegaskan bahwa Pemerintah Kota Kendari terus berkomitmen dalam upaya percepatan penurunan angka stunting melalui berbagai program yang melibatkan seluruh perangkat daerah.</p>\n\n\n\n<p>Ia juga berharap adanya dukungan dan kerja sama dari masyarakat untuk bersama-sama mencegah dan menanggani stunting sejak dini. Melalui kegiatan pendampingan ini, diharapkan anak-anak yang mengalami stunting dapat memperoleh perhatian lebih, sehingga pertumbuhan dan perkembangan mereka dapat semakin membaik.</p>\n\n\n\n<p>Pemerintah Kota Kendari sendiri terus menggalakkan berbagai program intervensi, baik melalui pemberian makanan tambahan, edukasi gizi, maupun pendampingan kepada keluarga yang memiliki anak berisiko stunting.</p>\n\n\n\n<p>Kegiatan ini juga menjadi bentuk kepedulian pemerintah daerah dalam memastikan setiap anak di Kota Kendari mendapatkan hak yang sama untuk tumbuh sehat dan berkembang secara optimal. Dengan adanya pendampingan secara langsung oleh para pejabat daerah sebagai orang tua asuh stunting, diharapkan penanganan stunting dapat dilakukan secara lebih efektif dan berkelanjutan.</p>\n', '2026-03-06', 'berita/leQjEy66EG.webp', '2', '2026-09-23 23:15:04', '2026-09-26 12:30:02'),
('266', '62396', 'https://berita.kendarikota.go.id/diskominfo-kota-kendari-gelar-buka-puasa-bersama-kadis-ajak-pegawai-perkuat-kebersamaan/', '10', 'Diskominfo Kota Kendari Gelar Buka Puasa Bersama, Kadis Ajak Pegawai Perkuat Kebersamaan', 'diskominfo-kota-kendari-gelar-buka-puasa-bersama-kadis-ajak-pegawai-perkuat-kebersamaan', '\n<p>Kendari, kendarikota.go.id – Dinas Komunikasi dan Informatika Kota Kendari menggelar kegiatan buka puasa bersama di salah satu rumah makan di Kota Kendari, Kamis (5/3/2026).</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img loading=\"lazy\" decoding=\"async\" width=\"675\" height=\"624\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260305-WA0315.jpg\" alt class=\"wp-image-62400\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260305-WA0315.jpg 675w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260305-WA0315-300x277.jpg 300w\" sizes=\"(max-width: 675px) 100vw, 675px\" /></figure>\n\n\n\n<p>Kegiatan tersebut diikuti oleh seluruh jajaran pegawai lingkup Diskominfo Kota Kendari sebagai momentum mempererat kebersamaan di bulan suci Ramadan 1447 Hijriah. Suasana penuh kehangatan dan kekeluargaan tampak mewarnai acara yang digelar secara sederhana namun khidmat tersebut.</p>\n\n\n\n<p>Kepala Dinas Komunikasi dan Informatika Kota Kendari, Sahuriyanto Meronda, menyampaikan bahwa buka puasa bersama ini bukan sekadar agenda rutin tahunan, tetapi menjadi ajang memperkuat silaturahmi antar pegawai.</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img loading=\"lazy\" decoding=\"async\" width=\"1280\" height=\"719\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260305-WA0317.jpg\" alt class=\"wp-image-62402\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260305-WA0317.jpg 1280w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260305-WA0317-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260305-WA0317-1024x575.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260305-WA0317-768x431.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260305-WA0317-750x421.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260305-WA0317-1140x640.jpg 1140w\" sizes=\"(max-width: 1280px) 100vw, 1280px\" /></figure>\n\n\n\n<p>Menurutnya, bulan Ramadan adalah waktu yang tepat untuk mempererat hubungan emosional dan membangun solidaritas dalam lingkungan kerja. Ia menekankan pentingnya menjaga kekompakan dan kerja sama tim demi mendukung kelancaran pelaksanaan tugas dan pelayanan kepada masyarakat.</p>\n\n\n\n<p>“Melalui momentum Ramadan ini, mari kita tingkatkan kebersamaan, saling mendukung, dan menjaga semangat kerja,” ujarnya.</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img loading=\"lazy\" decoding=\"async\" width=\"675\" height=\"506\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260305-WA0318-1.jpg\" alt class=\"wp-image-62403\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260305-WA0318-1.jpg 675w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260305-WA0318-1-300x225.jpg 300w\" sizes=\"(max-width: 675px) 100vw, 675px\" /></figure>\n\n\n\n<p>Mantan Kadis Pertanian ini, juga mengajak seluruh pegawai untuk terus meningkatkan disiplin, profesionalisme, serta tanggung jawab dalam menjalankan tugas masing-masing.</p>\n\n\n\n<p>Selain itu, ia mengingatkan bahwa Diskominfo memiliki peran strategis dalam penyebarluasan informasi pembangunan dan program pemerintah kepada masyarakat. Oleh karena itu, kekompakan internal menjadi modal utama dalam mewujudkan pelayanan informasi yang cepat, tepat, dan akurat.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"575\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260305-WA0317-1-1024x575.jpg\" alt class=\"wp-image-62404\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260305-WA0317-1-1024x575.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260305-WA0317-1-300x169.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260305-WA0317-1-768x431.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260305-WA0317-1-750x421.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260305-WA0317-1-1140x640.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/03/IMG-20260305-WA0317-1.jpg 1280w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Dalam kesempatan tersebut, Sahurianto juga menyampaikan apresiasi atas dedikasi dan kinerja seluruh pegawai selama ini.</p>\n\n\n\n<p>Ia berharap semangat kebersamaan yang terbangun dalam kegiatan buka puasa bersama dapat terus terjaga, tidak hanya selama Ramadhan tetapi juga dalam keseharian di lingkungan kerja.</p>\n\n\n\n<p>Kegiatan diawali dengan tausiyah singkat yang memberikan pesan-pesan spiritual tentang pentingnya menjaga ukhuwah dan meningkatkan ketakwaan.</p>\n\n\n\n<p>Para pegawai tampak antusias mengikuti rangkaian acara hingga waktu berbuka tiba. Saat adzan Maghrib berkumandang, seluruh peserta bersama-sama membatalkan puasa dan melanjutkan dengan makan malam bersama. Momentum tersebut menjadi sarana mempererat komunikasi informal antar pegawai di luar suasana kantor.</p>\n\n\n\n<p>Kegiatan buka puasa bersama ini diharapkan mampu memperkuat rasa persaudaraan serta meningkatkan semangat kebersamaan dalam mendukung program Pemerintah Kota Kendari.</p>\n\n\n\n<p>Dengan terjalinnya hubungan yang harmonis antar pegawai, Diskominfo Kota Kendari optimistis dapat terus memberikan pelayanan informasi terbaik bagi masyarakat.</p>\n\n\n\n<p>Melalui kebersamaan dan sinergi yang kuat, seluruh jajaran Diskominfo berkomitmen untuk terus berkontribusi dalam pembangunan Kota Kendari yang semakin maju dan sejahtera.</p>\n', '2026-03-05', 'berita/pjAo7DVML9.webp', '2', '2026-09-23 23:15:04', '2026-09-26 12:30:02'),
('267', '61453', 'https://berita.kendarikota.go.id/kominfo-konsel-studi-tiru-ke-kendari-bahas-tata-kelola-kemitraan-media-yang-transparan/', '10', 'Kominfo Konsel Studi Tiru ke Kendari, Bahas Tata Kelola Kemitraan Media yang Transparan', 'kominfo-konsel-studi-tiru-ke-kendari-bahas-tata-kelola-kemitraan-media-yang-transparan', '\n<p>Kendari, kendarikota.go.id– Dinas Komunikasi dan Informatika (Kominfo) Kabupaten Konawe Selatan melakukan kunjungan dinas ke Dinas Kominfo Kota Kendari untuk berkonsultasi sekaligus berkoordinasi terkait pengelolaan kemitraan pemerintah daerah dengan media. Pertemuan ini menjadi ruang berbagi praktik terbaik dalam membangun kerja sama publikasi yang profesional, transparan, dan akuntabel.</p>\n\n\n\n<p>Rombongan Kominfo Konawe Selatan dipimpin langsung Kepala Dinas bersama Kepala Bidang Informasi dan Komunikasi Publik (Infokom). Kehadiran mereka disambut jajaran Kominfo Kota Kendari yang memfasilitasi diskusi teknis mengenai tata kelola kemitraan dengan media elektronik, media cetak, hingga media online.</p>\n\n\n\n<p>Pembahasan difokuskan pada mekanisme kerja sama yang tertib administrasi, selektif, serta berorientasi pada kualitas diseminasi informasi publik. Kedua instansi juga mendalami pemanfaatan platform e-katalog dalam pengadaan jasa publikasi pemerintah, termasuk alur perencanaan, pelaksanaan, hingga pelaporan hasil kerja sama sebagai bentuk pertanggungjawaban kinerja.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-11 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"768\" data-id=\"61455\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/02/IMG-20260206-WA0261-1024x768.jpg\" alt class=\"wp-image-61455\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/02/IMG-20260206-WA0261-1024x768.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/02/IMG-20260206-WA0261-300x225.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/02/IMG-20260206-WA0261-768x576.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/02/IMG-20260206-WA0261-1536x1152.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/02/IMG-20260206-WA0261-2048x1536.jpg 2048w, https://berita.kendarikota.go.id/wp-content/uploads/2026/02/IMG-20260206-WA0261-750x563.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/02/IMG-20260206-WA0261-1140x855.jpg 1140w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n</figure>\n\n\n\n<p>Kepala Dinas Kominfo Kota Kendari, Sahuriyanto, menilai kunjungan ini sebagai langkah positif dalam memperkuat sinergi antardaerah dalam pengelolaan informasi publik.</p>\n\n\n\n<p>“Kemitraan media bukan sekadar kerja sama publikasi, tetapi bagian dari upaya pemerintah menghadirkan informasi yang akurat, berimbang, dan mudah diakses masyarakat. Karena itu, tata kelolanya harus rapi, transparan, dan bisa dipertanggungjawabkan,” ujar Sahuriyanto, Jumat (6/2/2026).</p>\n\n\n\n<p>Ia menjelaskan, Kominfo Kota Kendari selama ini menata pola kemitraan dengan prinsip akuntabilitas, mulai dari proses perencanaan kebutuhan publikasi, penggunaan e-katalog, hingga evaluasi hasil kerja sama. Pendekatan ini dinilai mampu menjaga kualitas relasi pemerintah dengan media sekaligus memastikan anggaran digunakan secara efektif.</p>\n\n\n\n<p>Dalam diskusi, turut dibahas mekanisme pelaporan hasil kegiatan publikasi sebagai bahan evaluasi kinerja dan dasar perbaikan di periode berikutnya. Langkah tersebut penting agar kemitraan media tidak hanya berorientasi pada output tayangan, tetapi juga pada dampak penyebaran informasi kepada masyarakat.</p>\n\n\n\n<p>Pihak Kominfo Konawe Selatan berharap, melalui kunjungan ini, mereka memperoleh referensi konkret untuk menyempurnakan sistem kemitraan media di daerahnya. Selain itu, kolaborasi ini diharapkan dapat memperkuat jaringan komunikasi antarpemerintah daerah dalam mendukung penyebaran informasi publik yang efektif.</p>\n\n\n\n<p>Pertemuan ditutup dengan komitmen kedua belah pihak untuk terus menjalin komunikasi dan berbagi pengalaman, sehingga tata kelola kemitraan media di masing-masing daerah semakin tertib, profesional, dan berorientasi pada pelayanan informasi kepada masyarakat.</p>\n\n\n\n<p>Saat menerima kunjungan Dinas Kominfo Kabupaten Konawe Selatan, Kadis Kominfo Kota Kendari didampingi Kabid Infokom dan Kabid E Goverment.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"768\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/02/IMG-20260206-WA0263-1024x768.jpg\" alt class=\"wp-image-61456\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/02/IMG-20260206-WA0263-1024x768.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/02/IMG-20260206-WA0263-300x225.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/02/IMG-20260206-WA0263-768x576.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/02/IMG-20260206-WA0263-1536x1152.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/02/IMG-20260206-WA0263-2048x1536.jpg 2048w, https://berita.kendarikota.go.id/wp-content/uploads/2026/02/IMG-20260206-WA0263-750x563.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/02/IMG-20260206-WA0263-1140x855.jpg 1140w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n', '2026-02-06', 'berita/uGP2EZGcIF.webp', '2', '2026-09-23 23:15:04', '2026-09-26 12:30:01'),
('268', '59924', 'https://berita.kendarikota.go.id/kadis-kominfo-kendari-buka-dea-pemasaran-digital-berbasis-ai-batch-xxi/', '10', 'Kadis Kominfo Kendari Buka DEA Pemasaran Digital Berbasis AI Batch XXI', 'kadis-kominfo-kendari-buka-dea-pemasaran-digital-berbasis-ai-batch-xxi', '\n<p>Kendari, kendarikota.go.id – Kepala Dinas Komunikasi dan Informatika (Kominfo) Kota Kendari, Sahuriyanto, membuka kegiatan Digital Entrepreneurship Academy (DEA) Pemasaran Digital dengan Kecerdasan Buatan (AI) Batch XXI Kota Kendari. Kegiatan ini digelar di Universitas Mandala Waluya pada Senin, (15/12/2025), sebagai bagian dari program penguatan kapasitas pelaku usaha dan sumber daya manusia di bidang digital.</p>\n\n\n\n<p>Dalam sambutannya, Sahuriyanto menegaskan bahwa perkembangan teknologi kecerdasan buatan telah membawa perubahan signifikan dalam dunia pemasaran.</p>\n\n\n\n<p>“Oleh karena itu, pelaku usaha dan generasi muda dituntut untuk adaptif serta mampu memanfaatkan teknologi AI sebagai alat strategis dalam meningkatkan daya saing produk dan jasa,” ungkapnya.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"768\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0070-1024x768.jpg\" alt class=\"wp-image-59926\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0070-1024x768.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0070-300x225.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0070-768x576.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0070-750x563.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0070-1140x855.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0070.jpg 1280w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Sebanyak 35 peserta mengikuti pelatihan Pemasaran Digital dengan Kecerdasan Buatan (AI) ini. Peserta berasal dari berbagai latar belakang, mulai dari pelaku UMKM, mahasiswa, hingga masyarakat umum yang memiliki ketertarikan terhadap pengembangan usaha berbasis digital.</p>\n\n\n\n<p>Materi pelatihan mencakup pemahaman dasar AI untuk pemasaran, riset pasar dan penyusunan persona pembeli dengan AI, pembuatan konten teks, gambar, dan video berbasis AI, hingga optimasi kampanye digital serta analisis data. Seluruh materi disampaikan oleh instruktur berpengalaman di bidang pemasaran digital dan teknologi informasi.</p>\n\n\n\n<p>Selain penyampaian materi, kegiatan ini juga menjadi wadah kolaborasi antara Pemerintah Kota Kendari, BBPSDMP Kominfo Makassar, dan Universitas Mandala Waluya. Sinergi tersebut diharapkan mampu mendorong lahirnya wirausaha digital yang inovatif dan berdaya saing tinggi di era transformasi digital.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"768\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0065-1024x768.jpg\" alt class=\"wp-image-59929\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0065-1024x768.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0065-300x225.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0065-768x576.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0065-750x563.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0065-1140x855.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0065.jpg 1280w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Melalui pelaksanaan DEA Batch XXI ini, Pemerintah Kota Kendari berharap peserta dapat menyusun rencana aksi nyata dan mengimplementasikan pengetahuan yang diperoleh untuk mengembangkan usaha masing-masing. Program ini menjadi salah satu langkah strategis dalam mendukung pertumbuhan ekonomi digital dan peningkatan kualitas sumber daya manusia di Kota Kendari.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-12 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"768\" height=\"1024\" data-id=\"59928\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0069-768x1024.jpg\" alt class=\"wp-image-59928\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0069-768x1024.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0069-225x300.jpg 225w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0069-1152x1536.jpg 1152w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0069-750x1000.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0069-1140x1520.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0069.jpg 1200w\" sizes=\"(max-width: 768px) 100vw, 768px\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"768\" data-id=\"59930\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0063-1024x768.jpg\" alt class=\"wp-image-59930\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0063-1024x768.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0063-300x225.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0063-768x576.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0063-750x563.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0063-1140x855.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/IMG-20251215-WA0063.jpg 1280w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n</figure>\n', '2025-12-15', 'berita/O7v28WUrTi.webp', '3', '2026-09-23 23:15:04', '2026-09-26 12:29:58'),
('269', '59537', 'https://berita.kendarikota.go.id/call-center-112-kendari-terima-3-218-panggilan-pada-november-kominfo-soroti-peningkatan-laporan-valid/', '10', 'Call Center 112 Kendari Terima 3.218 Panggilan pada November, Kominfo Soroti Peningkatan Laporan Valid', 'call-center-112-kendari-terima-3218-panggilan-pada-november-kominfo-soroti-peningkatan-laporan-valid', '\n<p>Kendari, kendarikota.go.id – Layanan darurat Call Center 112 Kota Kendari mencatat 3.218 panggilan masuk sepanjang November 2025. Data resmi Dinas Komunikasi dan Informatika (Kominfo) Kota Kendari menunjukkan peningkatan kualitas layanan sekaligus tingginya kesadaran masyarakat dalam memanfaatkan layanan darurat.</p>\n\n\n\n<p>Dari total panggilan tersebut, 2.527 di antaranya merupakan panggilan valid, sementara 691 sisanya tercatat sebagai panggilan tidak valid atau ghost call. Secara persentase, tingkat panggilan valid mencapai 79 persen, angka yang disebut sebagai capaian positif oleh Dinas Kominfo.</p>\n\n\n\n<p>Kepala Dinas Kominfo Kota Kendari, Sahuriyanto Meronda, mengapresiasi kerja petugas 112 yang terus siaga selama 24 jam. Ia mengatakan bahwa peningkatan laporan valid menunjukkan semakin banyak warga yang memanfaatkan kanal darurat ini secara tepat.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"768\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2025/12/ebb9dda9-4cb4-4317-8b89-8b7450400aa1-1024x768.jpeg\" alt class=\"wp-image-59539\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2025/12/ebb9dda9-4cb4-4317-8b89-8b7450400aa1-1024x768.jpeg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/ebb9dda9-4cb4-4317-8b89-8b7450400aa1-300x225.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/ebb9dda9-4cb4-4317-8b89-8b7450400aa1-768x576.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/ebb9dda9-4cb4-4317-8b89-8b7450400aa1-1536x1152.jpeg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/ebb9dda9-4cb4-4317-8b89-8b7450400aa1-2048x1536.jpeg 2048w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/ebb9dda9-4cb4-4317-8b89-8b7450400aa1-750x563.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/ebb9dda9-4cb4-4317-8b89-8b7450400aa1-1140x855.jpeg 1140w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>“Call Center 112 semakin dipercaya masyarakat. Data bulan November memperlihatkan bahwa laporan valid mendominasi, ini menandakan kesadaran warga terhadap layanan darurat semakin baik. Namun kami tetap mengimbau agar masyarakat tidak melakukan prank call karena sangat mengganggu penanganan laporan yang sifatnya mendesak,” ujarnya.</p>\n\n\n\n<p>Dari hasil rekapitulasi, sebanyak 118 tiket laporan dibuat oleh petugas call taker. Jenis kejadian yang paling sering dilaporkan adalah gangguan PLN dengan 27 laporan, dilanjutkan permintaan penebangan pohon sebanyak 22 laporan, serta perbaikan lampu penerangan jalan umum (LPJU) sebanyak 15 laporan. Laporan lainnya meliputi gangguan ketertiban warga, tawuran, hingga pohon tumbang.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"663\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2025/12/feef4c5d-271b-43fb-a244-cfaee13f4ec4-1024x663.jpeg\" alt class=\"wp-image-59540\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2025/12/feef4c5d-271b-43fb-a244-cfaee13f4ec4-1024x663.jpeg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/feef4c5d-271b-43fb-a244-cfaee13f4ec4-300x194.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/feef4c5d-271b-43fb-a244-cfaee13f4ec4-768x497.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/feef4c5d-271b-43fb-a244-cfaee13f4ec4-750x485.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/feef4c5d-271b-43fb-a244-cfaee13f4ec4.jpeg 1080w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Respons instansi terkait juga menjadi sorotan dalam laporan bulanan ini. PLN menindaklanjuti seluruh laporan gangguan listrik yang masuk. DLHK menyelesaikan 14 dari 24 laporan penanganan pohon, sementara Dinas Perhubungan menyelesaikan 9 dari 18 laporan perbaikan LPJU. Instansi lain seperti BPBD, Satpol PP, dan Dinas Kesehatan turut melakukan penanganan sesuai jenis laporan yang masuk.</p>\n\n\n\n<p>Secara keseluruhan, dari 118 laporan yang diterbitkan, 95 di antaranya telah selesai ditindaklanjuti, sementara 23 laporan masih dalam proses penyelesaian. Beberapa laporan juga dinyatakan tidak sesuai dengan tugas instansi tujuan sehingga memerlukan koordinasi lebih lanjut.</p>\n\n\n\n<p>Sahuriyanto menegaskan bahwa, evaluasi rutin akan terus dilakukan untuk memperkuat kualitas layanan, termasuk mempercepat respons lintas instansi dan menekan angka panggilan tidak valid.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"768\" height=\"1024\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2025/12/6c198cb7-b2df-44f1-afae-c83da51d8cd7-768x1024.jpeg\" alt class=\"wp-image-59541\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2025/12/6c198cb7-b2df-44f1-afae-c83da51d8cd7-768x1024.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/6c198cb7-b2df-44f1-afae-c83da51d8cd7-225x300.jpeg 225w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/6c198cb7-b2df-44f1-afae-c83da51d8cd7-1152x1536.jpeg 1152w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/6c198cb7-b2df-44f1-afae-c83da51d8cd7-750x1000.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/6c198cb7-b2df-44f1-afae-c83da51d8cd7-1140x1520.jpeg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/6c198cb7-b2df-44f1-afae-c83da51d8cd7.jpeg 1200w\" sizes=\"(max-width: 768px) 100vw, 768px\" /></figure>\n\n\n\n<p>“Kominfo bersama seluruh instansi terkait terus berkomitmen meningkatkan kecepatan penanganan. Kami berharap masyarakat tetap menjadikan 112 sebagai kanal utama dalam keadaan darurat. Kolaborasi yang baik antara pemerintah dan warga akan membuat layanan ini semakin optimal,” tutupnya.</p>\n\n\n\n<p>Laporan November ini menjadi bahan evaluasi Pemkot Kendari dalam penguatan sistem layanan darurat yang lebih responsif, terintegrasi, dan berorientasi pada keselamatan warga.</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img loading=\"lazy\" decoding=\"async\" width=\"944\" height=\"562\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2025/12/9058b50c-601f-4c31-a0df-d7e5d0b4f2d4.jpeg\" alt class=\"wp-image-59542\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2025/12/9058b50c-601f-4c31-a0df-d7e5d0b4f2d4.jpeg 944w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/9058b50c-601f-4c31-a0df-d7e5d0b4f2d4-300x179.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/9058b50c-601f-4c31-a0df-d7e5d0b4f2d4-768x457.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2025/12/9058b50c-601f-4c31-a0df-d7e5d0b4f2d4-750x447.jpeg 750w\" sizes=\"(max-width: 944px) 100vw, 944px\" /></figure>\n', '2025-12-02', 'berita/aoAlVki3fK.webp', '2', '2026-09-23 23:15:04', '2026-09-26 12:29:57'),
('270', '69274', 'https://berita.kendarikota.go.id/kadis-kominfo-kendari-wakili-wali-kota-di-upacara-hut-postel-ke-81-di-balmon-kendari/', '10', 'Kadis Kominfo Kendari Wakili Wali Kota di Upacara HUT Postel ke-81 di Balmon Kendari', 'kadis-kominfo-kendari-wakili-wali-kota-di-upacara-hut-postel-ke-81-di-balmon-kendari', '\n<p>Kendari, kendarikota.go.id – Kepala Dinas Komunikasi dan Informatika (Kominfo) Kota Kendari, Sahuriyanto Meronda, SP., MM. , mewakili Wali Kota Kendari menghadiri upacara peringatan Hari Ulang Tahun (HUT) Pos dan Telekomunikasi (Postel) ke-81 yang d igelar di halaman Kantor Balai Monitor Spektrum Frekuensi Radio Kelas II Kendari, Minggu (27/9/2026).</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img decoding=\"async\" width=\"768\" height=\"1024\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0030-768x1024.jpg\" alt class=\"wp-image-69276\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0030-768x1024.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0030-225x300.jpg 225w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0030-750x1000.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0030.jpg 960w\" sizes=\"(max-width: 768px) 100vw, 768px\" /></figure>\n\n\n\n<p>Upacara peringatan tersebut dipimpin langsung oleh Kepala Balai Monitor Spektrum Frekuensi Radio (Balmon) Kendari atau Loka Monitor SFR Kendari, Boby Satriyo Suleman, S.H., M.H. Kegiatan berlangsung khidmat dengan diikuti oleh jajaran pegawai Balai Monitor dan perwakilan Forum Perangkat Daerah lingkup Kota Kendari.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img decoding=\"async\" width=\"1024\" height=\"768\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0028-1024x768.jpg\" alt class=\"wp-image-69277\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0028-1024x768.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0028-300x225.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0028-768x576.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0028-1536x1152.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0028-2048x1536.jpg 2048w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0028-750x563.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0028-1140x855.jpg 1140w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Dalam amanatnya, Kepala Balmon Kendari menyampaikan bahwa peringatan HUT Postel ke-81 menjadi momentum penting untuk memperkuat komitmen dalam menjaga dan mengelola spektrum frekuensi radio sebagai sumber daya strategis negara. Ia menegaskan pentingnya sinergi antara pemerintah pusat dan daerah dalam pengawasan dan penertiban frekuensi.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img decoding=\"async\" width=\"1024\" height=\"768\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0031-1024x768.jpg\" alt class=\"wp-image-69278\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0031-1024x768.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0031-300x225.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0031-768x576.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0031-1536x1152.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0031-2048x1536.jpg 2048w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0031-750x563.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0031-1140x855.jpg 1140w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Sementara itu, Kadis Kominfo Kota Kendari, Sahuriyanto, yang hadir mewakili Wali Kota Kendari menyampaikan apresiasi atas peran Balai Monitor SFR Kendari dalam mendukung tata kelola telekomunikasi yang tertib di wilayah Sulawesi Tenggara, khususnya Kota Kendari.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"768\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0037-1024x768.jpg\" alt class=\"wp-image-69279\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0037-1024x768.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0037-300x225.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0037-768x576.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0037-1536x1152.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0037-2048x1536.jpg 2048w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0037-750x563.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0037-1140x855.jpg 1140w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Menurutnya, di era digital saat ini, peran pengawasan spektrum frekuensi sangat vital untuk menjamin kelancaran komunikasi publik, layanan internet, hingga penyiaran. Pemerintah Kota Kendari berkomitmen untuk terus bersinergi dengan Balmon dalam mewujudkan ekosistem telekomunikasi yang sehat dan berkeadilan.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"768\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0038-1024x768.jpg\" alt class=\"wp-image-69280\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0038-1024x768.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0038-300x225.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0038-768x576.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0038-1536x1152.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0038-2048x1536.jpg 2048w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0038-750x563.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/09/IMG-20260927-WA0038-1140x855.jpg 1140w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Peringatan HUT Postel ke-81 tahun ini mengusung semangat transformasi digital yang inklusif dan berkelanjutan. Kegiatan upacara ditutup dengan doa bersama dan ramah tamah antar instansi sebagai bentuk penguatan kolaborasi lintas sektor di bidang komunikasi dan informatika.</p>\n\n\n\n<p>Turut hadir dalam upacara tersebut perwakilan dari sejumlah OPD, unsur TNI-Polri, serta stakeholder telekomunikasi dan penyiaran di Kota Kendari.</p>\n', '2026-09-27', 'berita/9biiQRDy2x.webp', '9', '2026-09-27 15:00:04', '2026-10-25 05:07:50'),
('271', '69429', 'https://berita.kendarikota.go.id/kadis-kominfo-kendari-kedatangan-kpk-di-balai-kota-kendari-agenda-monitoring-mcp-bukan-pengusutan-kasus/', '10', 'Kadis Kominfo Kendari: Kedatangan KPK di Balai Kota Kendari: Agenda Monitoring MCP, Bukan Pengusutan Kasus', 'kadis-kominfo-kendari-kedatangan-kpk-di-balai-kota-kendari-agenda-monitoring-mcp-bukan-pengusutan-kasus', '\n<p>Kendari, kendarikota.go.id – Pemerintah Kota Kendari meluruskan informasi terkait kedatangan Tim Komisi Pemberantasan Korupsi (KPK) di Balai Kota Kendari yang menjadi perhatian masyarakat, Rabu (30/9/2026).</p>\n\n\n\n<p>Kepala Dinas Komunikasi dan Informatika (Diskominfo) Kota Kendari, Sahuriyanto Meronda, S.P., M.M., menegaskan bahwa kedatangan Tim KPK tersebut merupakan agenda monitoring Monitoring Center for Prevention (MCP).</p>\n\n\n\n<p>Ia menjelaskan, kegiatan tersebut berkaitan dengan monitoring dan evaluasi terhadap pelaksanaan program pencegahan korupsi di lingkungan pemerintah daerah.</p>\n\n\n\n<p>“Perlu kami luruskan bahwa kedatangan Tim KPK di Balai Kota Kendari adalah agenda monitoring MCP, bukan pengusutan kasus,” tegas Sahuriyanto.</p>\n\n\n\n<p>Menurutnya, monitoring MCP merupakan bagian dari upaya mendorong pemerintah daerah untuk terus memperbaiki tata kelola pemerintahan serta memperkuat sistem pencegahan korupsi.</p>\n\n\n\n<p>Melalui agenda tersebut, pemerintah daerah dapat melakukan evaluasi terhadap berbagai aspek tata kelola pemerintahan yang menjadi bagian dari indikator pencegahan korupsi.</p>\n\n\n\n<p>Sahuriyanto mengatakan, Pemerintah Kota Kendari menyambut baik pelaksanaan monitoring tersebut sebagai bagian dari upaya memperkuat tata kelola pemerintahan yang transparan dan akuntabel.</p>\n\n\n\n<p>“Kami mendukung proses monitoring MCP karena ini menjadi bagian dari evaluasi dan penguatan tata kelola pemerintahan di Kota Kendari,” ujarnya.</p>\n\n\n\n<p>Ia menambahkan, perangkat daerah terkait terus berkoordinasi dalam menyiapkan data dan informasi yang diperlukan dalam proses monitoring dan evaluasi.</p>\n\n\n\n<p>Menurut Sahuriyanto, kegiatan monitoring juga menjadi kesempatan bagi pemerintah daerah untuk mengetahui bagian-bagian yang masih perlu diperbaiki dalam pelaksanaan tata kelola pemerintahan.</p>\n\n\n\n<p>Ia mengimbau masyarakat agar tidak mudah mempercayai informasi yang belum terverifikasi mengenai kedatangan Tim KPK di Balai Kota Kendari.</p>\n\n\n\n<p>“Jangan sampai agenda monitoring MCP dipahami sebagai pemeriksaan atau pengusutan kasus. Kami mengajak masyarakat untuk mendapatkan informasi dari sumber yang jelas dan dapat dipertanggungjawabkan,” kata Sahuriyanto.</p>\n\n\n\n<p>Pemerintah Kota Kendari, lanjutnya, akan terus mendukung berbagai upaya penguatan pencegahan korupsi melalui perbaikan sistem dan peningkatan kualitas tata kelola pemerintahan.</p>\n\n\n\n<p>Sahuriyanto berharap pelaksanaan monitoring MCP dapat memberikan masukan bagi Pemkot Kendari dalam meningkatkan kualitas penyelenggaraan pemerintahan dan pelayanan kepada masyarakat.</p>\n\n\n\n<p>Dengan adanya koordinasi dan evaluasi secara berkelanjutan, Pemerintah Kota Kendari berkomitmen memperkuat tata kelola pemerintahan yang transparan, akuntabel, serta berorientasi pada kepentingan masyarakat.</p>\n', '2026-10-01', 'berita/yDz12VMqvk.webp', '5', '2026-10-01 09:00:05', '2026-10-25 05:07:34'),
('272', '69789', 'https://berita.kendarikota.go.id/kadis-kominfo-kendari-terima-pendataan-lanjutan-sensus-ekonomi-2026-dari-bps/', '10', 'Kadis Kominfo Kendari Terima Pendataan Lanjutan Sensus Ekonomi 2026 dari BPS', 'kadis-kominfo-kendari-terima-pendataan-lanjutan-sensus-ekonomi-2026-dari-bps', '\n<p>Kendari, kendarikota.go.id – Kepala Dinas Komunikasi dan Informatika (Kominfo) Kota Kendari, Sahuriyanto Meronda, menerima kunjungan Kepala Badan Pusat Statistik (BPS) Kota Kendari, Hj. Sultriawati Efendy dalam rangka pelaksanaan pendataan lanjutan Sensus Ekonomi 2026 (SE2026). Kegiatan tersebut berlangsung di ruang Command Center Dinas Kominfo Kota Kendari, Senin (12/10/2026).</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-1 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img decoding=\"async\" width=\"768\" height=\"1024\" data-id=\"69790\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/9a4c3ca9-e3e4-4baf-ae23-c629f9fd0b5b-768x1024.jpeg\" alt class=\"wp-image-69790\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/9a4c3ca9-e3e4-4baf-ae23-c629f9fd0b5b-768x1024.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/9a4c3ca9-e3e4-4baf-ae23-c629f9fd0b5b-225x300.jpeg 225w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/9a4c3ca9-e3e4-4baf-ae23-c629f9fd0b5b-1152x1536.jpeg 1152w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/9a4c3ca9-e3e4-4baf-ae23-c629f9fd0b5b-1536x2048.jpeg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/9a4c3ca9-e3e4-4baf-ae23-c629f9fd0b5b-750x1000.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/9a4c3ca9-e3e4-4baf-ae23-c629f9fd0b5b-1140x1520.jpeg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/9a4c3ca9-e3e4-4baf-ae23-c629f9fd0b5b-scaled.jpeg 1920w\" sizes=\"(max-width: 768px) 100vw, 768px\" /></figure>\n</figure>\n\n\n\n<p>Pendataan ini merupakan tindak lanjut dari kegiatan Sensus Ekonomi 2026 yang dilaksanakan BPS Kota Kendari untuk memperoleh data mengenai unit usaha dan keluarga di wilayah Kota Kendari. Berdasarkan hasil evaluasi cakupan pendataan, masih ditemukan sejumlah Aparatur Sipil Negara (ASN) di lingkungan Dinas Kominfo Kota Kendari yang belum tercakup dalam pendataan SE2026.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-2 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img decoding=\"async\" width=\"1024\" height=\"768\" data-id=\"69791\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG_2383-1024x768.jpeg\" alt class=\"wp-image-69791\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG_2383-1024x768.jpeg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG_2383-300x225.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG_2383-768x576.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG_2383-1536x1152.jpeg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG_2383-2048x1536.jpeg 2048w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG_2383-750x563.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG_2383-1140x855.jpeg 1140w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n</figure>\n\n\n\n<p>Melalui kegiatan tersebut, BPS Kota Kendari melakukan pendataan terhadap ASN yang belum terdata guna memastikan cakupan sensus berjalan secara menyeluruh. Pelaksanaan pendataan ini juga menjadi bagian dari upaya meningkatkan kelengkapan dan kualitas data statistik yang dibutuhkan dalam menggambarkan kondisi perekonomian masyarakat.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-3 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img decoding=\"async\" width=\"1024\" height=\"768\" data-id=\"69792\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG_2401-1024x768.jpeg\" alt class=\"wp-image-69792\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG_2401-1024x768.jpeg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG_2401-300x225.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG_2401-768x576.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG_2401-1536x1152.jpeg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG_2401-2048x1536.jpeg 2048w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG_2401-750x563.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG_2401-1140x855.jpeg 1140w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n</figure>\n\n\n\n<p>Sebelumnya, melalui surat Nomor B-859/74710/SS.190/2026 tertanggal 9 Oktober 2026, BPS Kota Kendari meminta dukungan Dinas Kominfo Kota Kendari untuk memfasilitasi petugas sensus dalam melakukan pendataan pada Senin, 12 Oktober 2026, mulai pukul 08.30 WITA. ASN yang namanya tercantum dalam daftar diminta menerima kunjungan petugas sensus dan menyiapkan dokumen pendukung yang diperlukan.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-4 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"768\" height=\"1024\" data-id=\"69793\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/8d60c973-9ce7-42fb-ac5a-c055db2de71f-768x1024.jpeg\" alt class=\"wp-image-69793\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/8d60c973-9ce7-42fb-ac5a-c055db2de71f-768x1024.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/8d60c973-9ce7-42fb-ac5a-c055db2de71f-225x300.jpeg 225w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/8d60c973-9ce7-42fb-ac5a-c055db2de71f-1152x1536.jpeg 1152w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/8d60c973-9ce7-42fb-ac5a-c055db2de71f-1536x2048.jpeg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/8d60c973-9ce7-42fb-ac5a-c055db2de71f-750x1000.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/8d60c973-9ce7-42fb-ac5a-c055db2de71f-1140x1520.jpeg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/8d60c973-9ce7-42fb-ac5a-c055db2de71f-scaled.jpeg 1920w\" sizes=\"(max-width: 768px) 100vw, 768px\" /></figure>\n</figure>\n\n\n\n<p>Adapun dokumen yang perlu disiapkan dalam proses pendataan tersebut meliputi Kartu Keluarga (KK) dan nomor identitas pelanggan Perusahaan Listrik Negara (PLN). Kesiapan dokumen ini diharapkan dapat membantu memperlancar proses pengumpulan data serta meminimalkan kendala selama pelaksanaan sensus.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"768\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG-20261012-WA0023-1024x768.jpg\" alt class=\"wp-image-69798\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG-20261012-WA0023-1024x768.jpg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG-20261012-WA0023-300x225.jpg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG-20261012-WA0023-768x576.jpg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG-20261012-WA0023-1536x1152.jpg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG-20261012-WA0023-750x563.jpg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG-20261012-WA0023-1140x855.jpg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG-20261012-WA0023.jpg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n\n\n\n<p>Kadis Kominfo Kota Kendari, Sahuriyanto Meronda, mendukung pelaksanaan pendataan tersebut sebagai bagian dari upaya menyukseskan program nasional Sensus Ekonomi 2026. Dukungan dan koordinasi antara perangkat daerah dan BPS diharapkan dapat memastikan seluruh ASN yang menjadi sasaran pendataan memperoleh pelayanan sesuai prosedur, sehingga data yang dikumpulkan lebih lengkap dan akurat.</p>\n\n\n\n<p>Melalui pelaksanaan pendataan lanjutan ini, Pemerintah Kota Kendari berharap sinergi dengan BPS terus terjalin dalam mendukung penyediaan data statistik yang berkualitas. Data hasil Sensus Ekonomi 2026 diharapkan dapat menjadi salah satu dasar penting dalam perencanaan pembangunan, perumusan kebijakan, serta pengambilan keputusan yang mendukung pertumbuhan ekonomi dan kesejahteraan masyarakat Kota Kendari.</p>\n', '2026-10-12', 'berita/PDfq4PbOyo.webp', '2', '2026-10-12 15:00:05', '2026-10-20 14:57:55'),
('273', '69850', 'https://berita.kendarikota.go.id/diskominfo-kendari-bersama-opd-bahas-optimalisasi-penggunaan-internet-untuk-dukung-kinerja-pemerintahan/', '10', 'Diskominfo Kendari Bersama OPD Bahas Optimalisasi Penggunaan Internet untuk Dukung Kinerja Pemerintahan', 'diskominfo-kendari-bersama-opd-bahas-optimalisasi-penggunaan-internet-untuk-dukung-kinerja-pemerintahan', '\n<p>Kendari, kendarikota.go.id – Kepala Dinas Komunikasi dan Informatika (Diskominfo) Kota Kendari, Sahuriyanto Meronda, memimpin rapat optimalisasi penggunaan internet bersama Sekretaris Diskominfo Kota Kendari, Wawan Astanto, Sekretaris Inspektorat Kota Kendari, Rusdin Jaya, Kepala Bidang Teknologi Informasi dan Komunikasi (TIK) Alim Rawis, Kepala Bidang Informasi dan Komunikasi Publik (IKP) Adi Supriadi, serta perwakilan organisasi perangkat daerah (OPD) lingkup Pemerintah Kota Kendari, di Ruang Rapat Kantor Diskominfo Kota Kendari, Selasa (13/10/2026).</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-1 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img decoding=\"async\" width=\"1024\" height=\"768\" data-id=\"69851\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/cb7608c9-9e24-4bda-9908-c8312dd51e83-1024x768.jpeg\" alt class=\"wp-image-69851\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/cb7608c9-9e24-4bda-9908-c8312dd51e83-1024x768.jpeg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/cb7608c9-9e24-4bda-9908-c8312dd51e83-300x225.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/cb7608c9-9e24-4bda-9908-c8312dd51e83-768x576.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/cb7608c9-9e24-4bda-9908-c8312dd51e83-750x563.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/cb7608c9-9e24-4bda-9908-c8312dd51e83-1140x855.jpeg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/cb7608c9-9e24-4bda-9908-c8312dd51e83.jpeg 1280w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n</figure>\n\n\n\n<p>Rapat ini membahas evaluasi penggunaan layanan internet serta kebutuhan peningkatan infrastruktur jaringan untuk menunjang kelancaran pelaksanaan tugas pemerintahan dan pelayanan publik berbasis digital.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-2 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img decoding=\"async\" width=\"1024\" height=\"768\" data-id=\"69859\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/79daeaa6-0180-4c88-af7a-4f1d74a10ae7-1024x768.jpeg\" alt class=\"wp-image-69859\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/79daeaa6-0180-4c88-af7a-4f1d74a10ae7-1024x768.jpeg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/79daeaa6-0180-4c88-af7a-4f1d74a10ae7-300x225.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/79daeaa6-0180-4c88-af7a-4f1d74a10ae7-768x576.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/79daeaa6-0180-4c88-af7a-4f1d74a10ae7-1536x1152.jpeg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/79daeaa6-0180-4c88-af7a-4f1d74a10ae7-750x563.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/79daeaa6-0180-4c88-af7a-4f1d74a10ae7-1140x855.jpeg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/79daeaa6-0180-4c88-af7a-4f1d74a10ae7.jpeg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n</figure>\n\n\n\n<p>Dalam pembahasan terungkap bahwa peningkatan kapasitas bandwidth masih diperlukan untuk mengakomodasi kebutuhan konektivitas perangkat daerah. Selain itu, penerapan manajemen bandwidth menjadi salah satu langkah yang diusulkan agar distribusi akses internet dapat diatur secara lebih efektif sesuai kebutuhan masing-masing OPD.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-3 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img decoding=\"async\" width=\"1024\" height=\"768\" data-id=\"69858\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/5b2e1b2c-f87c-4b74-853d-d726f1763fb5-1024x768.jpeg\" alt class=\"wp-image-69858\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/5b2e1b2c-f87c-4b74-853d-d726f1763fb5-1024x768.jpeg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/5b2e1b2c-f87c-4b74-853d-d726f1763fb5-300x225.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/5b2e1b2c-f87c-4b74-853d-d726f1763fb5-768x576.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/5b2e1b2c-f87c-4b74-853d-d726f1763fb5-1536x1152.jpeg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/5b2e1b2c-f87c-4b74-853d-d726f1763fb5-750x563.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/5b2e1b2c-f87c-4b74-853d-d726f1763fb5-1140x855.jpeg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/5b2e1b2c-f87c-4b74-853d-d726f1763fb5.jpeg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n</figure>\n\n\n\n<p>Kepala Diskominfo Kota Kendari, Sahuriyanto Meronda, mengatakan bahwa optimalisasi penggunaan internet merupakan bagian dari upaya meningkatkan kualitas dukungan teknologi informasi bagi perangkat daerah.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-4 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"768\" data-id=\"69854\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG_2603-1024x768.jpeg\" alt class=\"wp-image-69854\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG_2603-1024x768.jpeg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG_2603-300x225.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG_2603-768x576.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG_2603-1536x1152.jpeg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG_2603-2048x1536.jpeg 2048w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG_2603-750x563.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/IMG_2603-1140x855.jpeg 1140w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n</figure>\n\n\n\n<p>“Melalui koordinasi bersama OPD, kita berupaya meningkatkan kualitas layanan internet agar semakin optimal dalam mendukung kinerja aparatur dan percepatan transformasi digital Pemerintah Kota Kendari,” ujar Kadis Sahuriyanto.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-5 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"768\" data-id=\"69855\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/a7458345-d2ce-42f6-8638-af0e7e824fb9-1024x768.jpeg\" alt class=\"wp-image-69855\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/a7458345-d2ce-42f6-8638-af0e7e824fb9-1024x768.jpeg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/a7458345-d2ce-42f6-8638-af0e7e824fb9-300x225.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/a7458345-d2ce-42f6-8638-af0e7e824fb9-768x576.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/a7458345-d2ce-42f6-8638-af0e7e824fb9-750x563.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/a7458345-d2ce-42f6-8638-af0e7e824fb9-1140x855.jpeg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/a7458345-d2ce-42f6-8638-af0e7e824fb9.jpeg 1280w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n</figure>\n\n\n\n<p>Sebagai tindak lanjut pembahasan, rapat mengusulkan penambahan kapasitas bandwidth serta perbaikan kualitas sarana dan prasarana jaringan internet, baik di gedung Balai Kota Kendari maupun pada OPD yang berkantor di luar kawasan tersebut. Penambahan perangkat pendukung, termasuk access Point yang memadai, juga menjadi perhatian untuk memperluas jangkauan dan meningkatkan kualitas akses internet di lokasi yang membutuhkan.</p>\n\n\n\n<p>Rapat ini juga melibatkan perwakilan sejumlah OPD, di antaranya, Badan Keuangan dan Aset Daerah (BKAD), Badan Perencanaan Pembangunan Daerah (Bappeda), Badan Pendapatan Daerah (Bapenda), Dinas Perhubungan, Dinas Kependudukan dan Pencatatan Sipil, Badan Kesatuan Bangsa dan Politik, Satuan Polisi Pamong Praja, Dinas Pariwisata dan Ekonomi Kreatif, Dinas Penanaman Modal dan Pelayanan Terpadu Satu Pintu (DPM-PTSP), Badan Kepegawaian dan Pengembangan Sumber Daya Manusia (BKPSDM), Dinas Perumahan, Kawasan Permukiman dan Pertanahan, serta Bagian Umum Sekretariat Daerah Kota Kendari.</p>\n\n\n\n<p>Melalui koordinasi lintas perangkat daerah ini, Diskominfo Kota Kendari mendorong peningkatan kualitas layanan internet yang disesuaikan dengan kebutuhan dan prioritas masing-masing OPD. Upaya tersebut diharapkan dapat mewujudkan konektivitas yang lebih stabil dan merata, meningkatkan produktivitas aparatur, serta mendukung penyelenggaraan pemerintahan yang efektif, terintegrasi, dan berbasis digital.</p>\n', '2026-10-13', 'berita/tZEZOAUSAB.webp', '2', '2026-10-13 15:00:04', '2026-10-25 05:07:47'),
('274', '69996', 'https://berita.kendarikota.go.id/family-gathering-di-pantai-nambo-kominfo-kendari-perkuat-kekompakan-dan-kolaborasi/', '10', 'Family Gathering di Pantai Nambo, Kominfo Kendari Perkuat Kekompakan dan Kolaborasi', 'family-gathering-di-pantai-nambo-kominfo-kendari-perkuat-kekompakan-dan-kolaborasi', '\n<p>Kendari, kendarikota.go.id – Dinas Komunikasi dan Informatika (Kominfo) Kota Kendari menggelar family gathering di kawasan Pantai Nambo, Sabtu (17/10/2026).</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-1 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img decoding=\"async\" width=\"1024\" height=\"684\" data-id=\"69998\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/17d1f184-b17c-49ad-8808-1587984ca4a8-1024x684.jpeg\" alt class=\"wp-image-69998\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/17d1f184-b17c-49ad-8808-1587984ca4a8-1024x684.jpeg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/17d1f184-b17c-49ad-8808-1587984ca4a8-300x200.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/17d1f184-b17c-49ad-8808-1587984ca4a8-768x513.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/17d1f184-b17c-49ad-8808-1587984ca4a8-1536x1026.jpeg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/17d1f184-b17c-49ad-8808-1587984ca4a8-750x501.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/17d1f184-b17c-49ad-8808-1587984ca4a8-1140x762.jpeg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/17d1f184-b17c-49ad-8808-1587984ca4a8.jpeg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n</figure>\n\n\n\n<p>Kegiatan ini menjadi momentum mempererat silaturahmi, mencairkan komunikasi antarpegawai, serta membangun kekompakan untuk mendukung pelaksanaan tugas dan pelayanan kepada masyarakat.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-2 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img decoding=\"async\" width=\"1024\" height=\"768\" data-id=\"69997\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/de301353-48d6-4ab3-83f0-aa98e37d689a-1024x768.jpeg\" alt class=\"wp-image-69997\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/de301353-48d6-4ab3-83f0-aa98e37d689a-1024x768.jpeg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/de301353-48d6-4ab3-83f0-aa98e37d689a-300x225.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/de301353-48d6-4ab3-83f0-aa98e37d689a-768x576.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/de301353-48d6-4ab3-83f0-aa98e37d689a-1536x1152.jpeg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/de301353-48d6-4ab3-83f0-aa98e37d689a-750x563.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/de301353-48d6-4ab3-83f0-aa98e37d689a-1140x855.jpeg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/de301353-48d6-4ab3-83f0-aa98e37d689a.jpeg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n</figure>\n\n\n\n<p>Kepala Dinas Kominfo Kota Kendari, Sahuriyanto Meronda, mengatakan kegiatan tersebut tidak sekadar menjadi ajang berkumpul di luar lingkungan kerja. Family gathering juga diharapkan menciptakan suasana komunikasi yang lebih terbuka antara pimpinan dan staf, termasuk memperkuat hubungan lintas bidang.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-3 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img decoding=\"async\" width=\"1024\" height=\"684\" data-id=\"69999\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/865453b0-8164-4f5b-bb06-9d539586dbc1-1024x684.jpeg\" alt class=\"wp-image-69999\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/865453b0-8164-4f5b-bb06-9d539586dbc1-1024x684.jpeg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/865453b0-8164-4f5b-bb06-9d539586dbc1-300x200.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/865453b0-8164-4f5b-bb06-9d539586dbc1-768x513.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/865453b0-8164-4f5b-bb06-9d539586dbc1-1536x1026.jpeg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/865453b0-8164-4f5b-bb06-9d539586dbc1-750x501.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/865453b0-8164-4f5b-bb06-9d539586dbc1-1140x762.jpeg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/865453b0-8164-4f5b-bb06-9d539586dbc1.jpeg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n</figure>\n\n\n\n<p>“Dalam sebuah organisasi, komunikasi tidak boleh hanya berjalan baik antara pimpinan dan pejabat di atasnya. Hubungan komunikasi dengan staf di setiap tingkatan juga perlu dijaga agar koordinasi pekerjaan berjalan lebih efektif,” ungkapnya.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-4 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"684\" data-id=\"70000\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/6ed9c980-9e4f-4a2b-963e-fa037f04a91f-1024x684.jpeg\" alt class=\"wp-image-70000\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/6ed9c980-9e4f-4a2b-963e-fa037f04a91f-1024x684.jpeg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/6ed9c980-9e4f-4a2b-963e-fa037f04a91f-300x200.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/6ed9c980-9e4f-4a2b-963e-fa037f04a91f-768x513.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/6ed9c980-9e4f-4a2b-963e-fa037f04a91f-1536x1026.jpeg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/6ed9c980-9e4f-4a2b-963e-fa037f04a91f-750x501.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/6ed9c980-9e4f-4a2b-963e-fa037f04a91f-1140x762.jpeg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/6ed9c980-9e4f-4a2b-963e-fa037f04a91f.jpeg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n</figure>\n\n\n\n<p>Karena itu, kegiatan yang dikemas melalui permainan dan aktivitas kebersamaan tersebut diharapkan menjadi ruang untuk mencairkan suasana sekaligus membangun hubungan kerja yang lebih harmonis.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-5 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"684\" data-id=\"70001\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/dcb3c007-b375-4707-823e-fdb9f9cbfffc-1024x684.jpeg\" alt class=\"wp-image-70001\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/dcb3c007-b375-4707-823e-fdb9f9cbfffc-1024x684.jpeg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/dcb3c007-b375-4707-823e-fdb9f9cbfffc-300x200.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/dcb3c007-b375-4707-823e-fdb9f9cbfffc-768x513.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/dcb3c007-b375-4707-823e-fdb9f9cbfffc-1536x1026.jpeg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/dcb3c007-b375-4707-823e-fdb9f9cbfffc-750x501.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/dcb3c007-b375-4707-823e-fdb9f9cbfffc-1140x762.jpeg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/dcb3c007-b375-4707-823e-fdb9f9cbfffc.jpeg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n</figure>\n\n\n\n<p>Sahuriyanto mengingatkan peserta agar tidak menjadikan permainan sebagai ajang persaingan untuk mengejar kemenangan. Hal terpenting, kata dia, adalah kebersamaan, kegembiraan, dan kemampuan menjaga kekompakan di tengah perbedaan tugas dan tanggung jawab.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-6 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"684\" data-id=\"70002\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/626b44a1-f24b-495c-b476-f77ff7b5c1b5-1024x684.jpeg\" alt class=\"wp-image-70002\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/626b44a1-f24b-495c-b476-f77ff7b5c1b5-1024x684.jpeg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/626b44a1-f24b-495c-b476-f77ff7b5c1b5-300x200.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/626b44a1-f24b-495c-b476-f77ff7b5c1b5-768x513.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/626b44a1-f24b-495c-b476-f77ff7b5c1b5-1536x1026.jpeg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/626b44a1-f24b-495c-b476-f77ff7b5c1b5-750x501.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/626b44a1-f24b-495c-b476-f77ff7b5c1b5-1140x762.jpeg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/626b44a1-f24b-495c-b476-f77ff7b5c1b5.jpeg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n</figure>\n\n\n\n<p>Family gathering ini juga menjadi kegiatan resmi yang pertama kali diselenggarakan secara menyeluruh di lingkungan Dinas Kominfo Kota Kendari di bawah kepemimpinannya. Gagasan kegiatan tersebut berawal dari aspirasi pegawai yang kemudian mendapat dukungan pimpinan.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-7 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"684\" data-id=\"70003\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/8ec77f77-d048-495b-a3a9-09b93c77e750-1024x684.jpeg\" alt class=\"wp-image-70003\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/8ec77f77-d048-495b-a3a9-09b93c77e750-1024x684.jpeg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/8ec77f77-d048-495b-a3a9-09b93c77e750-300x200.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/8ec77f77-d048-495b-a3a9-09b93c77e750-768x513.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/8ec77f77-d048-495b-a3a9-09b93c77e750-1536x1026.jpeg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/8ec77f77-d048-495b-a3a9-09b93c77e750-750x501.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/8ec77f77-d048-495b-a3a9-09b93c77e750-1140x762.jpeg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/8ec77f77-d048-495b-a3a9-09b93c77e750.jpeg 1600w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n</figure>\n\n\n\n<p>Pendekatan tersebut menunjukkan bahwa ide untuk membangun suasana kerja yang lebih baik dapat tumbuh dari bawah, kemudian diwujudkan melalui dukungan bersama.</p>\n\n\n\n<p>Sekretaris Dinas Kominfo Kota Kendari, Wawan Astanto, menjelaskan kegiatan ini memiliki sejumlah tujuan strategis, yakni mempererat silaturahmi, memperkuat kolaborasi, serta meningkatkan profesionalisme dan kinerja pegawai.</p>\n\n\n\n<p>“Kebersamaan di luar kantor tetap perlu berjalan seiring dengan tanggung jawab profesional. Setiap pegawai diharapkan memahami tugas dan fungsi masing-masing sesuai struktur organisasi sehingga koordinasi dan pelaksanaan pekerjaan dapat berlangsung lebih baik,” katanya.</p>\n\n\n\n<p>Kegiatan tersebut diikuti pegawai Dinas Kominfo Kota Kendari, termasuk pejabat struktural, staf, serta peserta magang. Sejumlah wartawan juga turut hadir dalam kegiatan yang dirancang berlangsung santai dan penuh keakraban itu.</p>\n\n\n\n<p>Selain menjadi sarana memperkuat hubungan internal, family gathering diharapkan membuka ruang interaksi yang lebih cair antara pegawai dari berbagai bidang. Dengan komunikasi yang semakin baik, koordinasi dalam menjalankan program dan menyelesaikan pekerjaan diharapkan dapat berjalan lebih efektif.</p>\n\n\n\n<p>Melalui kegiatan di Pantai Nambo ini, Dinas Kominfo Kota Kendari berupaya membangun lingkungan kerja yang tidak hanya berorientasi pada pencapaian target, tetapi juga ditopang hubungan antarpersonel yang solid.</p>\n\n\n\n<p>Kebersamaan tersebut diharapkan menjadi modal untuk meningkatkan kolaborasi dan profesionalisme pegawai dalam menjalankan tugas komunikasi, informatika, serta pelayanan informasi publik di Kota Kendari.</p>\n', '2026-10-19', 'berita/XkoBDfgc7v.webp', '3', '2026-10-19 09:00:03', '2026-10-22 01:30:16'),
('275', '70077', 'https://berita.kendarikota.go.id/siswa-dirgantara-flight-school-kendari-kunjungi-command-center-diskominfo-kenali-pemanfaatan-teknologi-digital/', '10', 'Siswa Dirgantara Flight School Kendari Kunjungi Command Center Diskominfo, Kenali Pemanfaatan Teknologi Digital', 'siswa-dirgantara-flight-school-kendari-kunjungi-command-center-diskominfo-kenali-pemanfaatan-teknologi-digital', '\n<p>Kendari, kendarikota.go.id – Kepala Dinas Komunikasi dan Informatika (Diskominfo) Kota Kendari, Sahuriyanto Meronda, menerima kunjungan edukatif siswa-siswi Dirgantara Flight School Kendari di Command Center Diskominfo Kota Kendari, Selasa (20/10/2026).</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-1 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img decoding=\"async\" width=\"576\" height=\"1024\" data-id=\"70078\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/289b1165-fbd4-47e3-91ff-f7752f4688e6-576x1024.jpeg\" alt class=\"wp-image-70078\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/289b1165-fbd4-47e3-91ff-f7752f4688e6-576x1024.jpeg 576w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/289b1165-fbd4-47e3-91ff-f7752f4688e6-169x300.jpeg 169w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/289b1165-fbd4-47e3-91ff-f7752f4688e6-768x1365.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/289b1165-fbd4-47e3-91ff-f7752f4688e6-864x1536.jpeg 864w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/289b1165-fbd4-47e3-91ff-f7752f4688e6-1152x2048.jpeg 1152w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/289b1165-fbd4-47e3-91ff-f7752f4688e6-750x1333.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/289b1165-fbd4-47e3-91ff-f7752f4688e6-1140x2027.jpeg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/289b1165-fbd4-47e3-91ff-f7752f4688e6-scaled.jpeg 1440w\" sizes=\"(max-width: 576px) 100vw, 576px\" /></figure>\n</figure>\n\n\n\n<p>Kunjungan ini bertujuan memberikan wawasan kepada para siswa mengenai pemanfaatan teknologi informasi dan komunikasi dalam mendukung penyelenggaraan pemerintahan serta pelayanan publik.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-2 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img decoding=\"async\" width=\"1024\" height=\"576\" data-id=\"70079\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/dc7e29b5-0998-49ea-85b1-116494c42283-1024x576.jpeg\" alt class=\"wp-image-70079\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/dc7e29b5-0998-49ea-85b1-116494c42283-1024x576.jpeg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/dc7e29b5-0998-49ea-85b1-116494c42283-300x169.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/dc7e29b5-0998-49ea-85b1-116494c42283-768x432.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/dc7e29b5-0998-49ea-85b1-116494c42283-1536x864.jpeg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/dc7e29b5-0998-49ea-85b1-116494c42283-2048x1152.jpeg 2048w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/dc7e29b5-0998-49ea-85b1-116494c42283-750x422.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/dc7e29b5-0998-49ea-85b1-116494c42283-1140x641.jpeg 1140w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n</figure>\n\n\n\n<p>Kegiatan tersebut merupakan bagian dari pembelajaran di luar sekolah untuk memperluas pengetahuan siswa tentang perkembangan teknologi digital. Melalui kunjungan ini, para siswa berkesempatan melihat secara langsung bagaimana teknologi dimanfaatkan untuk mendukung pengelolaan informasi, pemantauan situasi, serta koordinasi dalam lingkup Pemerintah Kota Kendari.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-3 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img decoding=\"async\" width=\"1024\" height=\"576\" data-id=\"70080\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/13633ead-0aa0-4c2f-afa0-6616ff55c0fa-1024x576.jpeg\" alt class=\"wp-image-70080\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/13633ead-0aa0-4c2f-afa0-6616ff55c0fa-1024x576.jpeg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/13633ead-0aa0-4c2f-afa0-6616ff55c0fa-300x169.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/13633ead-0aa0-4c2f-afa0-6616ff55c0fa-768x432.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/13633ead-0aa0-4c2f-afa0-6616ff55c0fa-1536x864.jpeg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/13633ead-0aa0-4c2f-afa0-6616ff55c0fa-2048x1152.jpeg 2048w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/13633ead-0aa0-4c2f-afa0-6616ff55c0fa-750x422.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/13633ead-0aa0-4c2f-afa0-6616ff55c0fa-1140x641.jpeg 1140w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n</figure>\n\n\n\n<p>Kedatangan rombongan siswa disambut langsung oleh Kepala Diskominfo Kota Kendari di ruang Command Center. Dalam kesempatan tersebut, para siswa diperkenalkan dengan berbagai fasilitas teknologi yang tersedia, termasuk layar pemantauan informasi dan kamera pengawas yang menjadi bagian dari sistem pendukung pengelolaan informasi dan pemantauan kondisi wilayah.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-4 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"1024\" height=\"576\" data-id=\"70091\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/902a5da1-dab9-4ba1-95f8-462116ad088c-1024x576.jpeg\" alt class=\"wp-image-70091\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/902a5da1-dab9-4ba1-95f8-462116ad088c-1024x576.jpeg 1024w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/902a5da1-dab9-4ba1-95f8-462116ad088c-300x169.jpeg 300w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/902a5da1-dab9-4ba1-95f8-462116ad088c-768x432.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/902a5da1-dab9-4ba1-95f8-462116ad088c-1536x864.jpeg 1536w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/902a5da1-dab9-4ba1-95f8-462116ad088c-2048x1152.jpeg 2048w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/902a5da1-dab9-4ba1-95f8-462116ad088c-750x422.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/902a5da1-dab9-4ba1-95f8-462116ad088c-1140x641.jpeg 1140w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></figure>\n</figure>\n\n\n\n<p>Sahuriyanto Meronda menjelaskan bahwa perkembangan teknologi informasi memiliki peran penting dalam kehidupan masyarakat, termasuk dalam mendukung efektivitas pelayanan pemerintah. Ia berharap kunjungan tersebut dapat menambah pengetahuan siswa mengenai pemanfaatan teknologi sekaligus mendorong mereka untuk terus mengikuti perkembangan dunia digital.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-5 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"576\" height=\"1024\" data-id=\"70092\" src=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/a6c57ebf-fc78-4307-bcf4-08ca2ada6142-576x1024.jpeg\" alt class=\"wp-image-70092\" srcset=\"https://berita.kendarikota.go.id/wp-content/uploads/2026/10/a6c57ebf-fc78-4307-bcf4-08ca2ada6142-576x1024.jpeg 576w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/a6c57ebf-fc78-4307-bcf4-08ca2ada6142-169x300.jpeg 169w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/a6c57ebf-fc78-4307-bcf4-08ca2ada6142-768x1365.jpeg 768w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/a6c57ebf-fc78-4307-bcf4-08ca2ada6142-864x1536.jpeg 864w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/a6c57ebf-fc78-4307-bcf4-08ca2ada6142-1152x2048.jpeg 1152w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/a6c57ebf-fc78-4307-bcf4-08ca2ada6142-750x1333.jpeg 750w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/a6c57ebf-fc78-4307-bcf4-08ca2ada6142-1140x2027.jpeg 1140w, https://berita.kendarikota.go.id/wp-content/uploads/2026/10/a6c57ebf-fc78-4307-bcf4-08ca2ada6142-scaled.jpeg 1440w\" sizes=\"(max-width: 576px) 100vw, 576px\" /></figure>\n</figure>\n\n\n\n<p>“Kami berharap kunjungan ini dapat memberikan pengalaman dan wawasan baru bagi para siswa, sehingga mereka semakin mengenal teknologi informasi serta memahami manfaatnya dalam kehidupan sehari-hari,” ujarnya.</p>\n\n\n\n<p>Selama kegiatan berlangsung, para siswa tampak antusias menyimak penjelasan mengenai fungsi dan cara kerja Command Center. Mereka memperoleh gambaran tentang bagaimana teknologi digital, sistem komunikasi, dan pengelolaan informasi dapat dimanfaatkan untuk mendukung pelaksanaan tugas pemerintahan serta meningkatkan kualitas pelayanan kepada masyarakat.</p>\n\n\n\n<p>Kunjungan edukatif ini diharapkan dapat menumbuhkan rasa ingin tahu dan minat belajar para siswa terhadap perkembangan teknologi informasi dan komunikasi. Selain itu, pengalaman melihat langsung fasilitas Command Center diharapkan menjadi bekal pengetahuan bagi generasi muda untuk memanfaatkan teknologi secara bijak, positif, dan bertanggung jawab.</p>\n\n\n\n<p>Kegiatan tersebut sekaligus menjadi momentum untuk mempererat hubungan antara dunia pendidikan dan Pemerintah Kota Kendari. Melalui kegiatan pembelajaran seperti ini, Diskominfo Kota Kendari diharapkan dapat terus menjadi ruang edukasi bagi pelajar untuk mengenal penerapan teknologi digital sekaligus memahami peran komunikasi dan informasi dalam mendukung pembangunan daerah.</p>\n', '2026-10-21', 'berita/13OS12JzW8.webp', '2', '2026-10-21 09:00:03', '2026-10-26 08:49:59');
