INSERT INTO `dokumen` (`id`, `kategori_dokumen_id`, `judul`, `slug`, `deskripsi`, `file`, `total_unduhan`, `created_at`, `updated_at`) VALUES
('42', '5', 'Rencana Strategis Diskominfo Kota Kendari Tahun 2017-2022', 'rencana-strategis-diskominfo-kota-kendari-tahun-2017-2022', 'Renstra Dinas Komunikasi dan Informatika Kota Kendari sebagai penjabaran RPJMD Kota Kendari 2017-2022. Memuat visi, misi, tujuan, sasaran, strategi, arah kebijakan, serta program dan kegiatan urusan komunikasi dan informatika selama lima tahun.', 'dokumen/renstra-diskominfo-2017-2022.pdf', '5', '2026-03-12 09:14:27', '2026-10-25 05:08:04'),
('43', '6', 'Rencana Kerja (Renja) Diskominfo Kota Kendari Tahun 2019', 'rencana-kerja-renja-diskominfo-kota-kendari-tahun-2019', 'Rencana Kerja Organisasi Perangkat Daerah Dinas Komunikasi dan Informatika Kota Kendari tahun 2019. Berisi evaluasi pelaksanaan Renja tahun lalu, tujuan dan sasaran, serta rencana program dan kegiatan beserta pagu indikatifnya.', 'dokumen/renja-diskominfo-2019.pdf', '2', '2026-03-18 10:22:51', '2026-09-26 12:29:43'),
('44', '4', 'Evaluasi Rencana Aksi Kinerja Diskominfo Kota Kendari Tahun Anggaran 2019', 'evaluasi-rencana-aksi-kinerja-diskominfo-kota-kendari-tahun-anggaran-2019', 'Evaluasi rencana aksi kinerja Dinas Komunikasi dan Informatika Kota Kendari tahun anggaran 2019. Memuat sasaran, indikator, target, serta realisasi kinerja per triwulan untuk setiap program dan kegiatan.', 'dokumen/evaluasi-rencana-aksi-kinerja-2019.pdf', '4', '2026-04-07 14:05:09', '2026-10-25 05:07:58'),
('45', '1', 'Peraturan Daerah Kota Kendari Nomor 5 Tahun 2016 tentang Pembentukan dan Susunan Perangkat Daerah', 'peraturan-daerah-kota-kendari-nomor-5-tahun-2016-tentang-pembentukan-dan-susunan-perangkat-daerah', 'Perda yang menjadi dasar pembentukan perangkat daerah Kota Kendari, termasuk Dinas Komunikasi dan Informatika. Ditetapkan pada 17 Oktober 2016.', 'dokumen/perda-kendari-5-2016.pdf', '4', '2026-05-20 08:47:33', '2026-10-14 17:12:05'),
('46', '3', 'Keputusan Kepala Diskominfo Kota Kendari tentang Penetapan Indikator Kinerja Utama Tahun 2023', 'keputusan-kepala-diskominfo-kota-kendari-tentang-penetapan-indikator-kinerja-utama-tahun-2023', 'Keputusan Kepala Dinas Komunikasi dan Informatika Kota Kendari tentang penetapan Indikator Kinerja Utama (IKU) dinas tahun 2023 sebagai acuan pengukuran dan pelaporan kinerja.', 'dokumen/sk-iku-diskominfo-2023.pdf', '7', '2026-07-02 13:36:18', '2026-10-25 05:07:44'),
('47', '2', 'Peraturan Wali Kota Kendari Nomor 45 Tahun 2023 tentang Arsitektur Sistem Pemerintahan Berbasis Elektronik', 'peraturan-wali-kota-kendari-nomor-45-tahun-2023-tentang-arsitektur-sistem-pemerintahan-berbasis-elektronik', 'Perwali yang menetapkan Arsitektur SPBE Pemerintah Kota Kendari sebagai kerangka dasar integrasi proses bisnis, data, layanan, aplikasi, infrastruktur, dan keamanan SPBE. Ditetapkan pada 22 November 2023.', 'dokumen/perwali-kendari-45-2023.pdf', '5', '2026-08-14 10:12:45', '2026-10-22 02:57:13');
