INSERT INTO `profil_dinas` (`id`, `jenis`, `konten`, `created_at`, `updated_at`) VALUES
('1', 'sambutan-kadis', '<p>Sebagai institusi yang bertanggung jawab dalam bidang teknologi informasi dan komunikasi, kami berkomitmen untuk memberikan layanan terbaik guna mendukung transformasi digital dan mewujudkan Kota Kendari sebagai Smart City yang maju, inovatif, dan berdaya saing.</p><p>Website ini hadir sebagai sarana informasi dan komunikasi antara pemerintah dan masyarakat. Kami mengajak seluruh masyarakat Kota Kendari untuk bersama-sama memanfaatkan teknologi informasi guna menciptakan kota yang lebih cerdas, terhubung, dan sejahtera.</p><p>Dengan semangat kolaborasi dan inovasi, mari kita wujudkan visi Kota Kendari sebagai pusat pertumbuhan ekonomi digital dan teknologi di wilayah Indonesia Timur.</p>', '2026-09-03 11:20:35', '2026-09-03 11:20:35'),
('2', 'tagline-sambutan', '[{\"id\":1,\"value\":\"Transformasi Digital\"},{\"id\":2,\"value\":\"Inovasi Teknologi\"},{\"id\":3,\"value\":\"Layanan Publik Prima\"},{\"id\":4,\"value\":\"Keamanan Siber\"},{\"id\":5,\"value\":\"Literasi Digital\"},{\"id\":6,\"value\":\"Smart City Terdepan\"}]', '2026-09-03 11:20:35', '2026-09-23 22:53:10'),
('3', 'sejarah', '<p>Dinas Komunikasi dan Informatika (Diskominfo) Kota Kendari merupakan perangkat daerah yang memiliki peran strategis dalam mendukung transformasi digital pemerintahan serta penyelenggaraan layanan publik berbasis teknologi informasi. Sejak awal pembentukannya, Diskominfo Kota Kendari telah menunjukkan komitmen untuk menjadi penggerak utama dalam memodernisasi sistem informasi pemerintahan dan membangun keterhubungan antara pemerintah dan masyarakat.</p><p>Salah satu tonggak penting dalam sejarah Diskominfo adalah peluncuran <strong>Layanan Call Center 112 “Kendari Siaga”</strong>, yang merupakan sistem layanan darurat terpadu berbasis nasional. Layanan ini diluncurkan sebagai bagian dari upaya percepatan transformasi layanan publik, dan ditetapkan secara resmi melalui Surat Keputusan Wali Kota Kendari pada April 2022. Call Center 112 memungkinkan masyarakat mengakses bantuan darurat secara gratis dan cepat, hanya dengan satu nomor, tanpa harus mengingat banyak kontak instansi terkait.</p><p>Pada masa pandemi COVID-19, Diskominfo Kendari menunjukkan peran yang sangat aktif dalam penyebaran informasi, edukasi publik, serta penyelenggaraan berbagai aplikasi penunjang layanan pemerintahan. Aplikasi seperti <strong>Cov-Heroes</strong>, <strong>e-SPPD</strong>, <strong>LAIKA</strong>, dan <strong>JARI</strong> hadir sebagai solusi untuk mempercepat koordinasi dan pengambilan keputusan di tengah keterbatasan pertemuan fisik. Diskominfo juga secara intensif menyelenggarakan webinar literasi digital dan pelatihan keamanan siber, guna meningkatkan kesiapan masyarakat menghadapi era digital dan melawan hoaks.</p><p>Seiring dengan perkembangan teknologi, Diskominfo terus melahirkan berbagai inovasi baru. Beberapa di antaranya adalah <strong>Aplikasi Srikandi</strong> sebagai sistem kearsipan digital, <strong>E-Laika</strong> untuk manajemen surat menyurat tingkat RT/RW, dan <strong>E-Office</strong> sebagai platform tata kelola administrasi pemerintahan yang efisien dan terintegrasi. Aplikasi-aplikasi ini dirancang tidak hanya untuk meningkatkan kinerja aparatur, tetapi juga memberikan kemudahan layanan bagi masyarakat.</p><p>Melalui semangat kolaborasi dan inovasi, Diskominfo Kota Kendari terus meneguhkan eksistensinya sebagai motor penggerak digitalisasi pemerintahan. Dengan mengintegrasikan berbagai sistem informasi, memperkuat literasi digital, dan membangun Command Center sebagai pusat kendali kota, Diskominfo menjadi salah satu pilar utama dalam mewujudkan visi Kota Kendari sebagai Smart City yang terhubung, cerdas, dan berdaya saing di wilayah Indonesia Timur.</p>', '2026-09-03 11:20:35', '2026-09-22 11:58:32'),
('4', 'visi', '\"Terwujudnya Kota Kendari Tahun 2029 sebagai Kota Layak Huni yang Semakin Maju, Berdaya Saing, Adil, Sejahtera, dan Berkelanjutan.\"', '2026-09-03 11:20:35', '2026-09-03 11:20:35'),
('5', 'misi', '[{\"id\":1,\"value\":\"Menyediakan, memelihara dan mengembangkan berbagai fasilitas yang layak dan mencukupi untuk kebutuhan warga dan pengguna kota lainnya (yakni fasilitas umum, sosial, ruang publik, dan lainnya).\"},{\"id\":2,\"value\":\"Mewujudkan Tata Penyelenggaraan Kota yang baik (good city governance), meliputi tatakelola pemerintahan Kota yang baik, partisipasi warga kota yang baik dalam pengelolaan kota, dan juga kenyamanan bagi pengguna kota yang baik.\"},{\"id\":3,\"value\":\"Pembangunan Infrastruktur Kota yang terintegrasi, efisien, dan ramah lingkungan, dalam rangka memenuhi pelayanan dasar yang berkualitas.\"},{\"id\":4,\"value\":\"Peningkatan Pelayanan Sosial dan Kesejahteraan Warga Kota (Pendidikan, Kesehatan, dan lainnya).\"}]', '2026-09-03 11:20:35', '2026-09-23 22:52:53'),
('6', 'foto-diskominfo', '[{\"id\":1,\"value\":\"foto-diskominfo\\/mNuttyBNZR.webp\"},{\"id\":2,\"value\":\"foto-diskominfo\\/4F65ImC5q7.webp\"},{\"id\":3,\"value\":\"foto-diskominfo\\/bBSDvHAz4a.webp\"}]', '2026-09-03 11:20:35', '2026-09-24 01:36:00'),
('7', 'tugas', '<p>Berdasarkan <strong>Peraturan Wali Kota Kendari Nomor 20 Tahun 2022</strong>, Dinas Komunikasi dan Informatika mempunyai tugas:</p><p><em>“<strong>Melaksanakan urusan pemerintahan</strong> bidang <strong>komunikasi dan informatika</strong>, bidang <strong>persandian</strong>, dan bidang <strong>statistik</strong> sesuai dengan ketentuan peraturan perundang-undangan.”</em></p>', '2026-09-03 11:20:35', '2026-09-22 11:58:32'),
('8', 'fungsi', '[{\"id\":1,\"value\":\"Perumusan kebijakan teknis di bidang komunikasi dan informatika, persandian, dan statistik.\"},{\"id\":2,\"value\":\"Pelaksanaan kebijakan di bidang komunikasi dan informatika, persandian, dan statistik.\"},{\"id\":3,\"value\":\"Pelaksanaan evaluasi dan pelaporan di bidang komunikasi dan informatika, persandian, dan statistik.\"},{\"id\":4,\"value\":\"Pelaksanaan administrasi dinas sesuai dengan lingkup tugasnya.\"},{\"id\":5,\"value\":\"Pelaksanaan fungsi lain yang diberikan oleh Wali Kota sesuai dengan tugas dan fungsinya.\"}]', '2026-09-03 11:20:35', '2026-09-23 23:20:32'),
('9', 'struktur-organisasi', '', '2026-09-03 11:20:35', '2026-09-24 00:26:53'),
('10', 'pengaturan', '[{\"id\":\"telp\",\"value\":\"0822-4618-8268\"},{\"id\":\"email\",\"value\":\"diskominfokendari@gmail.com\"},{\"id\":\"alamat\",\"value\":\"Jl. Drs. H. Abdullah Silondae No.8 Lantai 9, Gedung Menara Balai Kota Kendari Pondambea, Kec. Kadia, Kota Kendari\"},{\"id\":\"fb\",\"value\":null},{\"id\":\"ig\",\"value\":null},{\"id\":\"tt\",\"value\":null},{\"id\":\"yt\",\"value\":null},{\"id\":\"survei_aktif\",\"value\":true},{\"id\":\"survei_url\",\"value\":\"https:\\/\\/surveidigital.spbe.go.id\\/embed\\/survey\\/eyJzdXJ2ZXlfaWQiOjIsInNlcnZpY2VfaWQiOjg2NSwiaG9zdCI6Imh0dHBzOi8vc3BwZC5rZW5kYXJpa290YS5nby5pZC8saHR0cDovL2xvY2FsaG9zdDo4MDA0Iiwia2V5Ijoia0NFZW9ySGgifQ==\\/embed\\/view\\/?jenis_layanan=SPPD%20Kota%20Kendari\"}]', '2026-09-03 11:20:35', '2026-09-23 15:44:01'),
('11', 'bagan-organisasi', '{\"nama\":\"Kepala Dinas\",\"pegawai_id\":26,\"anak\":[{\"nama\":\"Sekretariat\",\"pegawai_id\":null,\"posisi\":\"staf\",\"anak\":[{\"nama\":\"Subbagian Perencanaan dan Keuangan\",\"pegawai_id\":null},{\"nama\":\"Subbagian Umum dan Kepegawaian\",\"pegawai_id\":null}]},{\"nama\":\"Bidang Informasi dan Komunikasi Publik\",\"pegawai_id\":28,\"posisi\":\"lini\",\"anak\":[{\"nama\":\"Seksi Pengelolaan Informasi dan Komunikasi Publik\",\"pegawai_id\":null},{\"nama\":\"Seksi Hubungan Media dan Kehumasan\",\"pegawai_id\":null},{\"nama\":\"Seksi Pengelolaan Media dan Kanal Informasi\",\"pegawai_id\":null}]},{\"nama\":\"Bidang Penyelenggaraan E-government\",\"pegawai_id\":32,\"posisi\":\"lini\",\"anak\":[{\"nama\":\"Seksi Infrastruktur dan Teknologi Informasi\",\"pegawai_id\":null},{\"nama\":\"Seksi Pengembangan Aplikasi dan Sistem Informasi\",\"pegawai_id\":27},{\"nama\":\"Seksi Tata Kelola E-Government\",\"pegawai_id\":29}]},{\"nama\":\"Bidang Teknologi Informasi, Komunikasi, dan Persandian\",\"pegawai_id\":31,\"posisi\":\"lini\",\"anak\":[{\"nama\":\"Seksi Teknologi Informasi dan Pengelolaan Data\",\"pegawai_id\":null},{\"nama\":\"Seksi Keamanan Informasi dan Persandian\",\"pegawai_id\":null},{\"nama\":\"Seksi Telekomunikasi dan Infrastruktur Komunikasi\",\"pegawai_id\":null}]}]}', '2026-09-22 12:27:11', '2026-09-24 10:05:14'),
('17', 'sinkron-berita-atur', '{\"kata_kunci\":[\"kominfo\"],\"maks_per_sinkron\":10,\"aktif\":true}', '2026-09-23 14:43:11', '2026-09-23 23:15:12'),
('18', 'sinkron-berita', '{\"dijalankan\":\"2026-10-26T15:00:04+08:00\",\"baru\":0}', '2026-09-23 14:43:59', '2026-10-26 15:00:04');
INSERT INTO `profil_pimpinan` (`id`, `pegawai_id`, `foto`, `konten`, `created_at`, `updated_at`) VALUES
('1', '26', '[\"foto-kadis\\/rniQx7Gryo.webp\",\"foto-kadis\\/n9CwxF6hes.webp\",\"foto-kadis\\/8Ms8mt6Wfz.webp\"]', '<h3>Profil Singkat</h3><ul><li><p><strong>Nama:</strong> Sahuriyanto Meronda, SP., MM</p></li><li><p><strong>Jabatan:</strong> Kepala Dinas Komunikasi dan Informatika (Kominfo) Kota Kendari</p></li></ul><h3>Kegiatan Terkini</h3><ul><li><p><strong>Peluncuran layanan darurat <em>Call Center 112</em></strong> sebagai bagian dari program 100 hari kerja Pemerintah Kota Kendari yang terhubung dengan sistem darurat nasional pada Mei hingga Juni 2025</p></li><li><p><strong>Peresmian Command Center</strong> Kota Kendari bersama Wakil Wali Kota dan DPRD (23 Mei 2025)</p></li><li><p><strong>Tim publikasi digital</strong> Diskominfo menyambut HUT RI ke‑79 dengan kegiatan literasi dan dokumentasi publik</p></li><li><p><strong>Kunjungan dialogis di Looka Coffee Kendari</strong> bersama komunitas Gema Sultra (30 Mei 2025)</p></li></ul><h3>Inisiatif &amp; Fokus</h3><p>Inisiatif dan fokus Pemerintah Kota Kendari mencakup integrasi layanan publik melalui teknologi Call Center 112 yang bebas pulsa dan dapat diakses tanpa sinyal, serta optimalisasi Command Center sebagai pusat kendali informasi Kota Kendari. Untuk mendukung hal tersebut, dilakukan kolaborasi aktif dengan Kementerian Kominfo Republik Indonesia dan DPRD Kota Kendari, disertai peningkatan literasi digital melalui publikasi kegiatan dan pelatihan bagi masyarakat.</p>', '2026-09-03 11:20:35', '2026-09-24 09:49:41');
